import pandas as pd, json, re
from pathlib import Path

base = Path('data')

manual = (base/'manual.md').read_text()

# merchant lookup
merchants = json.loads((base/'merchant_data.json').read_text())
m = None
for row in merchants:
    if row.get('merchant_name') == 'Belles_cookbook_store':
        m = row
        break

if m is None:
    print("SUBMIT")
    print("Not Applicable")
    raise SystemExit

merchant_id = m.get('merchant_id')
mcc = str(m.get('mcc')) if m.get('mcc') is not None else None
country = m.get('country') or m.get('merchant_country') or m.get('billing_country')

# payments in March 2023 for this merchant
payments = pd.read_csv(base/'payments.csv')
date_col = None
for c in payments.columns:
    lc = c.lower()
    if 'date' in lc or 'created' in lc or 'timestamp' in lc:
        date_col = c
        break
if date_col is not None:
    payments[date_col] = pd.to_datetime(payments[date_col], errors='coerce')
    march = payments[(payments[date_col] >= '2023-03-01') & (payments[date_col] < '2023-04-01')]
else:
    march = payments.iloc[0:0]

merchant_cols = [c for c in payments.columns if 'merchant' in c.lower()]
march_m = march.iloc[0:0]
for c in merchant_cols:
    vals = march[c].astype(str)
    if merchant_id is not None and vals.eq(str(merchant_id)).any():
        march_m = march[vals.eq(str(merchant_id))]
        break
    if vals.eq('Belles_cookbook_store').any():
        march_m = march[vals.eq('Belles_cookbook_store')]
        break

# helper to evaluate fee applicability conservatively from manual/rules structure
fees = json.loads((base/'fees.json').read_text())
if isinstance(fees, dict):
    if 'fees' in fees and isinstance(fees['fees'], list):
        fees = fees['fees']
    else:
        fees = list(fees.values())

def norm(x):
    if x is None:
        return None
    return str(x).strip()

def matches_rule(rule):
    txt = json.dumps(rule).lower()
    # merchant-specific
    if 'belles_cookbook_store' in txt:
        return True
    if merchant_id is not None and str(merchant_id).lower() in txt:
        return True

    # if rule references MCC/category, require merchant MCC match if explicit values present
    if 'mcc' in txt and mcc is not None:
        vals = []
        if isinstance(rule, dict):
            for k,v in rule.items():
                if 'mcc' in str(k).lower():
                    if isinstance(v, list):
                        vals += [str(i) for i in v]
                    else:
                        vals += re.findall(r'\d+', str(v))
        if vals and mcc not in vals:
            return False

    # if rule references merchant country, require match if explicit
    if ('country' in txt or 'acquirer_country' in txt) and country is not None:
        vals = []
        if isinstance(rule, dict):
            for k,v in rule.items():
                lk = str(k).lower()
                if 'country' in lk:
                    if isinstance(v, list):
                        vals += [str(i) for i in v]
                    else:
                        vals += re.findall(r'[A-Z]{2}', str(v))
        if vals and country not in vals:
            return False

    # date applicability: must include March 2023 if dates are present
    if isinstance(rule, dict):
        start = None
        end = None
        for k,v in rule.items():
            lk = str(k).lower()
            if lk in ('start_date','effective_from','from','valid_from'):
                start = pd.to_datetime(v, errors='coerce')
            if lk in ('end_date','effective_to','to','valid_to'):
                end = pd.to_datetime(v, errors='coerce')
        march_start = pd.Timestamp('2023-03-01')
        march_end = pd.Timestamp('2023-03-31 23:59:59')
        if start is not None and pd.notna(start) and start > march_end:
            return False
        if end is not None and pd.notna(end) and end < march_start:
            return False

    return True

applicable = []
for fee in fees:
    fid = None
    if isinstance(fee, dict):
        fid = fee.get('fee_id') or fee.get('id') or fee.get('name')
        if matches_rule(fee):
            applicable.append(str(fid))
    else:
        continue

# If there are no March payments, no applicable fees for the month
if march_m.empty:
    applicable = []

# de-dup preserve order
seen = set()
applicable = [x for x in applicable if not (x in seen or seen.add(x))]

print("SUBMIT")
print(", ".join(applicable))
