import pandas as pd, json
df = pd.read_csv('data/payments.csv')
with open('data/fees.json') as f:
    fees = json.load(f)
with open('data/merchant_data.json') as f:
    md = json.load(f)
merchant_info = [m for m in md if m['merchant']=='Belles_cookbook_store'][0]
print(merchant_info)

b = df[df['merchant']=='Belles_cookbook_store'].copy()
b_jan = b[(b['day_of_year']>=1) & (b['day_of_year']<=31)]
frauds = b_jan[b_jan['has_fraudulent_dispute']==True].copy()

# Compute yearly monthly volume for January to determine bracket
jan_total_volume = b_jan['eur_amount'].sum()
print('Jan volume:', jan_total_volume)
jan_fraud_volume = frauds['eur_amount'].sum()
print('Jan fraud volume:', jan_fraud_volume)
print('fraud ratio:', jan_fraud_volume/jan_total_volume)

mcc = merchant_info['merchant_category_code']
acct = merchant_info['account_type']
cap_delay = merchant_info['capture_delay']
print('cap_delay:', cap_delay)

def matches(fee, tx, target_aci):
    if fee['card_scheme'] != tx['card_scheme']:
        return False
    if fee['account_type'] and acct not in fee['account_type']:
        return False
    if fee['merchant_category_code'] and mcc not in fee['merchant_category_code']:
        return False
    if fee['is_credit'] is not None and fee['is_credit'] != bool(tx['is_credit']):
        return False
    if fee['aci'] and target_aci not in fee['aci']:
        return False
    if fee['intracountry'] is not None:
        intra = (tx['issuing_country']==tx['acquirer_country'])
        if fee['intracountry'] != intra:
            return False
    # capture_delay
    if fee['capture_delay'] is not None:
        cd = fee['capture_delay']
        try:
            merch_cd = int(cap_delay)
        except:
            merch_cd = None
        if cd == 'manual':
            if cap_delay != 'manual': return False
        elif cd == 'immediate':
            if merch_cd != 0: return False
        elif cd == '<3':
            if merch_cd is None or not (merch_cd < 3): return False
        elif cd == '3-5':
            if merch_cd is None or not (3<=merch_cd<=5): return False
        elif cd == '>5':
            if merch_cd is None or not (merch_cd>5): return False
    # monthly_volume
    if fee['monthly_volume'] is not None:
        # skip check but treat as bracket-based - need to determine merchant volume
        pass
    if fee['monthly_fraud_level'] is not None:
        pass
    return True

# Check monthly_volume and fraud_level: compute for Belles in January
# Try to match strictly - include volume & fraud level checks
def parse_range(s, val):
    # like '100k-1m', '<3', '>5', '7.7%-8.3%'
    s = s.strip()
    def num(x):
        x=x.strip().replace('%','')
        mul=1
        if x.endswith('k'): mul=1000; x=x[:-1]
        elif x.endswith('m'): mul=1000000; x=x[:-1]
        return float(x)*mul
    if '-' in s and not s.startswith('-'):
        a,b=s.split('-')
        return num(a)<=val<=num(b)
    if s.startswith('<'):
        return val<num(s[1:])
    if s.startswith('>'):
        return val>num(s[1:])
    return True

def matches2(fee, tx, target_aci):
    if not matches(fee, tx, target_aci): return False
    if fee['monthly_volume'] is not None:
        if not parse_range(fee['monthly_volume'], jan_total_volume): return False
    if fee['monthly_fraud_level'] is not None:
        ratio = jan_fraud_volume/jan_total_volume*100
        if not parse_range(fee['monthly_fraud_level'], ratio): return False
    return True

acis = ['A','B','C','D','E','F','G']
results = {}
for aci in acis:
    total = 0
    unmatched = 0
    for _, tx in frauds.iterrows():
        matched = [f for f in fees if matches2(f, tx, aci)]
        if not matched:
            unmatched+=1
            continue
        # take the first (or smallest?)
        # use the (only) applicable fee - assume unique
        f = matched[0]
        fee_val = f['fixed_amount'] + f['rate']*tx['eur_amount']/10000
        total += fee_val
    results[aci] = (total, unmatched, len(frauds))

for k,v in results.items():
    print(k, v)
