def vol_match(rule):
    v=rule['monthly_volume']
    if v is None: return True
    def parse(x):
        x=x.replace('k','000').replace('m','000000')
        return float(x)
    if '-' in v:
        lo,hi=v.split('-')
        return parse(lo)<=monthly_volume<=parse(hi)
    if v.startswith('>'):
        return monthly_volume>parse(v[1:])
    if v.startswith('<'):
        return monthly_volume<parse(v[1:])
    return False

def fraud_match(rule):
    v=rule['monthly_fraud_level']
    if v is None: return True
    def parse(x):
        return float(x.replace('%',''))
    if '-' in v:
        lo,hi=v.split('-')
        return parse(lo)<=fraud_rate<=parse(hi)
    if v.startswith('>'):
        return fraud_rate>parse(v[1:])
    if v.startswith('<'):
        return fraud_rate<parse(v[1:])
    return False

def capture_match(rule):
    c=rule['capture_delay']
    if c is None: return True
    # merchant capture delay '1' -> less than 3 days
    # merchant value is '1' day
    md=1
    if c=='<3': return md<3
