import json

fees = json.load(open('fees.json'))

# Merchant characteristics
account_type='R'
mcc=5942
capture_delay='1'  # maps to '<3'
monthly_volume=118041.21
fraud_ratio=0.10559092032350398  # 10.56%

def cap_match(rule):
    v=rule['capture_delay']
    if v is None: return True
    # merchant capture delay = 1 day => '<3'
    if v=='<3': return True
    if v=='3-5': return False
    if v=='>5': return False
    if v=='immediate': return False
    if v=='manual': return False
    return False

def vol_match(rule):
    v=rule['monthly_volume']
    if v is None: return True
    # parse
    def parse(x):
        x=x.replace('k','000').replace('m','000000')
        return float(x)
    if '-' in v:
        lo,hi=v.split('-')
        return parse(lo)<=monthly_volume<=parse(hi) if hi else monthly_volume>=parse(lo)
    if v.startswith('>'):
        return monthly_volume>parse(v[1:])
    if v.startswith('<'):
        return monthly_volume<parse(v[1:])
    return False

def fraud_match(rule):
    v=rule['monthly_fraud_level']
    if v is None: return True
    fr=fraud_ratio*100
    if '-' in v:
        lo,hi=v.replace('%','').split('-')
        return float(lo)<=fr<=float(hi)
    if v.startswith('>'):
        return fr>float(v.replace('%','')[1:])
    if v.startswith('<'):
        return fr<float(v.replace('%','')[1:])
    return False

matched=[]
for r in fees:
    if r['account_type'] and account_type not in r['account_type']: continue
    if r['merchant_category_code'] and mcc not in r['merchant_category_code']: continue
    if not cap_match(r): continue
    if not vol_match(r): continue
    if not fraud_match(r): continue
    matched.append(r['ID'])

print(len(matched))
print(','.join(map(str,matched)))
