cd data && python3 << 'EOF'
import json, pandas as pd

fees = json.load(open('fees.json'))
df = pd.read_csv('payments.csv')

merchant = {'merchant':'Belles_cookbook_store','capture_delay':'1','account_type':'R','mcc':5942}

sub = df[(df['merchant']=='Belles_cookbook_store') & (df['year']==2023) & (df['day_of_year']==10)]

# monthly volume/fraud for January (days 1-31, 2023)
jan = df[(df['merchant']=='Belles_cookbook_store')&(df['year']==2023)&(df['day_of_year']>=1)&(df['day_of_year']<=31)]
vol = jan['eur_amount'].sum()
fraud_ratio = jan[jan['has_fraudulent_dispute']]['eur_amount'].sum()/vol*100
print('vol',vol,'fraud',fraud_ratio)

def vol_match(rule_vol, v):
    if rule_vol is None: return True
    s=rule_vol
    def parse(x):
        x=x.strip()
        if x.endswith('k'): return float(x[:-1])*1e3
        if x.endswith('m'): return float(x[:-1])*1e6
        return float(x)
    if '-' in s:
        lo,hi=s.split('-'); return parse(lo)<=v<parse(hi) or (parse(lo)<=v<=parse(hi))
    if s.startswith('>'): return v>parse(s[1:])
    if s.startswith('<'): return v<parse(s[1:])
    return False

def fraud_match(rule_f, f):
    if rule_f is None: return True
    s=rule_f
    def parse(x): return float(x.strip().replace('%',''))
    if '-' in s:
        lo,hi=s.split('-'); return parse(lo)<=f<=parse(hi)
    if s.startswith('>'): return f>parse(s[1:])
    if s.startswith('<'): return f<parse(s[1:])
    return False

def capture_match(rule_cd, mcd):
    if rule_cd is None: return True
    # merchant capture_delay = '1' -> means 1 day -> '<3'
    mv = int(mcd)  # 1
    if rule_cd=='immediate': return False
    if rule_cd=='manual': return False
    if rule_cd=='<3': return mv<3
    if rule_cd=='3-5': return 3<=mv<=5
    if rule_cd=='>5': return mv>5
    return False

applicable=set()
for r in fees:
    if r['card_scheme'] is not None and r['card_scheme'] not in sub['card_scheme'].unique():
        continue
    if r['account_type'] and 'R' not in r['account_type']:
        continue
    if r['merchant_category_code'] and 5942 not in r['merchant_category_code']:
        continue
    if not capture_match(r['capture_delay'], '1'):
        continue
    if not vol_match(r['monthly_volume'], vol):
        continue
    if not fraud_match(r['monthly_fraud_level'], fraud_ratio):
        continue
    # transaction-level: is_credit, aci, intracountry
    ok=False
    for _,t in sub.iterrows():
        if r['is_credit'] is not None and r['is_credit']!=bool(t['is_credit']): continue
        if r['aci'] and t['aci'] not in r['aci']: continue
        if r['intracountry'] is not None:
            intra = (t['issuing_country']==t['acquirer_country'])
            if r['intracountry']!=intra: continue
        ok=True; break
    if ok:
        applicable.add(r['ID'])

print(sorted(applicable))
print(len(applicable))
