import json, pandas as pd

fees = json.load(open('data/fees.json'))
p = pd.read_csv('data/payments.csv')
b = p[(p['merchant']=='Belles_cookbook_store') & (p['year']==2023) & (p['day_of_year']==10)].copy()

# merchant characteristics
mcc = 5942
acct = 'R'
cap_delay = '<3'  # 1 day
monthly_vol = '100k-1m'
monthly_fraud = '>8.3%'

def merchant_matches(f):
    if f['account_type'] and acct not in f['account_type']:
        return False
    if f['merchant_category_code'] and mcc not in f['merchant_category_code']:
        return False
    if f['capture_delay'] is not None and f['capture_delay'] != cap_delay:
        return False
    if f['monthly_volume'] is not None and f['monthly_volume'] != monthly_vol:
        return False
    if f['monthly_fraud_level'] is not None and f['monthly_fraud_level'] != monthly_fraud:
        return False
    return True

candidate = [f for f in fees if merchant_matches(f)]
print('Merchant-level candidates:', len(candidate))

# Now for each transaction on day 10, find matching fees
applicable = set()
for _, tx in b.iterrows():
    intracountry = (tx['issuing_country'] == tx['acquirer_country'])
    for f in candidate:
        if f['card_scheme'] != tx['card_scheme']:
            continue
        if f['is_credit'] is not None and f['is_credit'] != bool(tx['is_credit']):
            continue
        if f['aci'] and tx['aci'] not in f['aci']:
            continue
        if f['intracountry'] is not None:
            if bool(f['intracountry']) != intracountry:
                continue
        applicable.add(f['ID'])

print(sorted(applicable))
