import pandas as pd, json
fees = json.load(open('data/fees.json'))

def match(rule, tx_aci, card_scheme, is_credit, intracountry):
    if rule['card_scheme'] != card_scheme: return False
    at = rule['account_type']
    if at and 'R' not in at: return False
    cd = rule['capture_delay']
    if cd is not None and cd != '<3': return False
    mfl = rule['monthly_fraud_level']
    if mfl is not None:
        if '<' in mfl:
            v=float(mfl.replace('<','').replace('%',''))
            if not (10.3<v): return False
        elif '>' in mfl:
            v=float(mfl.replace('>','').replace('%',''))
            if not (10.3>v): return False
        elif '-' in mfl:
            lo,hi=mfl.split('-'); lo=float(lo.replace('%','')); hi=float(hi.replace('%',''))
            if not (lo<=10.3<=hi): return False
    mv = rule['monthly_volume']
    if mv is not None:
        def p(v): return int(v.replace('k','000').replace('m','000000'))
        if '<' in mv:
            if not (113260<p(mv.replace('<',''))): return False
        elif '>' in mv:
            if not (113260>p(mv.replace('>',''))): return False
        elif '-' in mv:
            lo,hi=mv.split('-')
            if not (p(lo)<=113260<=p(hi)): return False
    mcc = rule['merchant_category_code']
    if mcc and 5942 not in mcc: return False
    ic = rule['is_credit']
    if ic is not None and ic != is_credit: return False
    aci = rule['aci']
    if aci and tx_aci not in aci: return False
    intra = rule['intracountry']
    if intra is not None and bool(intra) != bool(intracountry): return False
    return True

# check per (scheme, aci, is_credit, intracountry) how many rules match
schemes=['GlobalCard','TransactPlus','NexPay','SwiftCharge']
for sc in schemes:
    for aci in ['A','B','C','D','E','F','G']:
        for isc in [True,False]:
            for ic in [True,False]:
                ms=[r for r in fees if match(r,aci,sc,isc,ic)]
                if len(ms)>1:
                    print(sc,aci,isc,ic,'->',len(ms),'rules IDs',[r['ID'] for r in ms])
