import pandas as pd, json
fees=json.load(open('data/fees.json'))
mcc=5942; acct='R'
total_vol=113260.42; fp=10.31
def match_fraud(rule_val,a):
    if rule_val is None: return True
    s=rule_val.replace('%','')
    if '-' in s: lo,hi=s.split('-'); return float(lo)<=a<=float(hi)
    if s.startswith('<'): return a<float(s[1:])
    if s.startswith('>'): return a>float(s[1:])
    return False
def match_volume(rv,a):
    if rv is None: return True
    def p(x):
        x=x.strip()
        if x.endswith('k'): return float(x[:-1])*1e3
        if x.endswith('m'): return float(x[:-1])*1e6
        return float(x)
    s=rv
    if '-' in s: lo,hi=s.split('-'); return p(lo)<=a<=p(hi)
    if s.startswith('<'): return a<p(s[1:])
    if s.startswith('>'): return a>p(s[1:])
def match_capture(rv,a):
    if rv is None: return True
    s=rv
    if s=='immediate': return a==0
    if s=='manual': return False
    if '-' in s: lo,hi=s.split('-'); return int(lo)<=a<=int(hi)
    if s.startswith('<'): return a<int(s[1:])
    if s.startswith('>'): return a>int(s[1:])
    return int(s)==a

for sch in ['GlobalCard','TransactPlus','NexPay','SwiftCharge']:
    print('---', sch, 'credit, intra=False ---')
    acis_found = set()
    for r in fees:
        if r['card_scheme']!=sch: continue
        if r['account_type'] and 'R' not in r['account_type']: continue
        if r['merchant_category_code'] and mcc not in r['merchant_category_code']: continue
        if r['is_credit'] is not None and r['is_credit']!=True: continue
        if not match_capture(r['capture_delay'],1): continue
        if not match_fraud(r['monthly_fraud_level'],fp): continue
        if not match_volume(r['monthly_volume'],total_vol): continue
        if r['intracountry'] is not None and bool(r['intracountry'])!=False: continue
        for a in (r['aci'] or ['ALL']):
            acis_found.add(a)
    print(acis_found)
