    'monthly_fraud_level': '>8.3%',
}

def match(fee):
    # account_type
    if fee['account_type'] and merchant['account_type'] not in fee['account_type']:
        return False
    # mcc
    if fee['merchant_category_code'] and merchant['mcc'] not in fee['merchant_category_code']:
        return False
    # capture_delay
    cd = fee['capture_delay']
    if cd is not None:
        # merchant capture_delay is 1 day -> "<3"
        if cd == '<3':
            ok = True
        elif cd == 'immediate':
            ok = False
        elif cd == '3-5':
            ok = False
        elif cd == '>5':
            ok = False
        elif cd == 'manual':
            ok = False
        else:
            ok = False
        if not ok:
            return False
    # monthly_volume
