import json
fees=json.load(open('data/fees.json'))

acct='R'; mcc=5942; capture='<3'  # capture_delay '1' -> before 3 days
vol=116436.32; fraud=10.248769456128466

def vol_match(rule):
    v=rule['monthly_volume']
    if v is None: return True
    # parse ranges like '100k-1m','<100k','>5m'
    def parse(x):
        x=x.replace('k','000').replace('m','000000')
        return float(x)
    if v.startswith('<'):
        return vol < parse(v[1:])
    if v.startswith('>'):
        return vol > parse(v[1:])
    lo,hi=v.split('-')
    return parse(lo)<=vol<=parse(hi)

def fraud_match(rule):
    f=rule['monthly_fraud_level']
    if f is None: return True
    if f.endswith('%'): f=f[:-1]
    if f.startswith('<'):
        return fraud < float(f[1:])
    if f.startswith('>'):
        return fraud > float(f[1:])
    lo,hi=f.split('-')
    return float(lo)<=fraud<=float(hi)

def cap_match(rule):
    c=rule['capture_delay']
    if c is None: return True
    return c==capture

matches=[]
for r in fees:
    if r['account_type'] and acct not in r['account_type']: continue
    if r['merchant_category_code'] and mcc not in r['merchant_category_code']: continue
    if not cap_match(r): continue
    if not vol_match(r): continue
    if not fraud_match(r): continue
    matches.append(r['ID'])
print(sorted(matches))
print(len(matches))
