import pandas as pd, json
df = pd.read_csv('data/payments.csv')
fees = json.load(open('data/fees.json'))

merchant = 'Belles_cookbook_store'
mcc = 5942
account_type = 'R'

b = df[(df.merchant==merchant) & (df.day_of_year<=31) & (df.year==2023)]
fr = b[b.has_fraudulent_dispute==True]
total_vol = b.eur_amount.sum()
fraud_rate = fr.eur_amount.sum()/total_vol*100

def match_mfl(mfl, fr_pct):
    if mfl.startswith('<'): return fr_pct < float(mfl[1:].replace('%',''))
    if mfl.startswith('>'): return fr_pct > float(mfl[1:].replace('%',''))
    parts = mfl.replace('%','').split('-')
    return float(parts[0]) <= fr_pct <= float(parts[1])

def match_mv(mv, tv):
    if mv == '100k-1m': return 100000 <= tv < 1000000
    if mv == '<100k': return tv < 100000
    if mv == '>1m': return tv >= 1000000
    if mv == '1m-5m': return 1000000 <= tv < 5000000
    if mv == '>5m': return tv >= 5000000
    return False

def match_fee(rule, tx):
    if rule['account_type'] and account_type not in rule['account_type']:
        return False
    if rule['merchant_category_code'] and mcc not in rule['merchant_category_code']:
        return False
    if rule['card_scheme'] != tx['card_scheme']:
        return False
    if rule['is_credit'] is not None and rule['is_credit'] != tx['is_credit']:
        return False
    if rule['aci'] and tx['aci'] not in rule['aci']:
        return False
    if rule['intracountry'] is not None:
        intra = (tx['issuing_country'] == tx['acquirer_country'])
        want = bool(rule['intracountry'])
        if want != intra:
            return False
    if rule['capture_delay'] is not None:
        if rule['capture_delay'] != '<3':
            return False
    if rule['monthly_fraud_level'] is not None:
        if not match_mfl(rule['monthly_fraud_level'], fraud_rate):
            return False
    if rule['monthly_volume'] is not None:
        if not match_mv(rule['monthly_volume'], total_vol):
            return False
    return True

acis = ['A','B','C','D','E','F','G']
for target_aci in acis:
    total_fee = 0
    unmatched = 0
    for _, tx in fr.iterrows():
        tx_dict = tx.to_dict()
        tx_dict['aci'] = target_aci
        matched = [r for r in fees if match_fee(r, tx_dict)]
        if not matched:
            unmatched += 1
            continue
        # If multiple match, take average? min? The manual doesn't specify.
        # Typically most specific applies - but for now compute both
        # Take mean of applicable
        fee = sum(r['fixed_amount'] + r['rate']*tx_dict['eur_amount']/10000 for r in matched)/len(matched)
        total_fee += fee
    print(f"ACI {target_aci}: fee_mean={total_fee:.2f}, unmatched={unmatched}")
