cd data && python3 << 'EOF'
import pandas as pd, json

df = pd.read_csv('payments.csv')
merch = [m for m in json.load(open('merchant_data.json')) if m['merchant']=='Crossfit_Hanna'][0]
fees = json.load(open('fees.json'))

t = df[df['merchant']=='Crossfit_Hanna'].copy()
t['date'] = pd.to_datetime(t['day_of_year']-1, unit='D', origin='2023-01-01')
t['month'] = t['date'].dt.month

monthly = t.groupby('month').agg(vol=('eur_amount','sum'),
    fraud=('eur_amount', lambda s: s[t.loc[s.index,'has_fraudulent_dispute']].sum())).to_dict('index')
mvol = {m:v['vol'] for m,v in monthly.items()}
mfraud = {m:v['fraud']/v['vol']*100 for m,v in monthly.items()}

def p(x):
    x=x.strip()
    if x.endswith('k'): return float(x[:-1])*1e3
    if x.endswith('m'): return float(x[:-1])*1e6
    return float(x)

def vol_match(rng, val):
    if rng is None: return True
    rng=rng.strip()
    if rng.startswith('>'): return val > p(rng[1:])
    if rng.startswith('<'): return val < p(rng[1:])
    lo,hi = rng.split('-')
    return p(lo) <= val < p(hi)

def fraud_match(rng, val):
    if rng is None: return True
    rng=rng.strip()
    if rng.startswith('>'): return val > float(rng[1:].replace('%',''))
    if rng.startswith('<'): return val < float(rng[1:].replace('%',''))
    lo,hi = rng.replace('%','').split('-')
    return float(lo) <= val <= float(hi)

def matches(rule, row, mv, mf):
    if rule['card_scheme'] != row['card_scheme']: return False
    if rule['account_type'] and merch['account_type'] not in rule['account_type']: return False
    if rule['capture_delay'] is not None and rule['capture_delay'] != merch['capture_delay']: return False
    if not fraud_match(rule['monthly_fraud_level'], mf): return False
    if not vol_match(rule['monthly_volume'], mv): return False
    if rule['merchant_category_code'] and merch['merchant_category_code'] not in rule['merchant_category_code']: return False
    if rule['is_credit'] is not None and rule['is_credit'] != row['is_credit']: return False
    if rule['aci'] and row['aci'] not in rule['aci']: return False
    if rule['intracountry'] is not None:
        intra = (row['issuing_country']==row['acquirer_country'])
        if bool(rule['intracountry']) != intra: return False
    return True

total = 0.0
unmatched = 0
for _, row in t.iterrows():
    mv = mvol[row['month']]; mf = mfraud[row['month']]
    fee = None
    for rule in fees:
        if matches(rule, row, mv, mf):
            fee = rule['fixed_amount'] + rule['rate']*row['eur_amount']/10000
            break
    if fee is None:
        unmatched += 1
    else:
        total += fee
print("unmatched:", unmatched)
print("total:", round(total,2))
