    if x.endswith('m'): return float(x[:-1])*1e6
    return float(x)
def in_vol(rng,v):
    if rng is None: return True
    rng=rng.strip()
    if rng.startswith('>'): return v>parse(rng[1:])
    if rng.startswith('<'): return v<parse(rng[1:])
    lo,hi=rng.split('-'); return parse(lo)<=v<=parse(hi)
def in_fraud(rng,v):
    if rng is None: return True
    rng=rng.strip()
    if rng.startswith('>'): return v>float(rng[1:].replace('%',''))
    if rng.startswith('<'): return v<float(rng[1:].replace('%',''))
    lo,hi=rng.replace('%','').split('-'); return float(lo)<=v<=float(hi)
def cap_match(rule,cap):
