import pandas as pd, json

with open('data/fees.json') as f:
    fees = json.load(f)

# Rafa_AI characteristics: account_type=D, MCC=7372, capture_delay=7 (>5)
# Monthly volume Oct = 210706 -> 100k-1m
# Monthly fraud level = ~10.6%

df = pd.read_csv('data/payments.csv')
rafa = df[df['merchant']=='Rafa_AI'].copy()
oct = rafa[(rafa['day_of_year']>=274)&(rafa['day_of_year']<=304)]
fraud = oct[oct['has_fraudulent_dispute']==True].copy()

# For each fraud transaction, we'd move ACI to a different one. Need to compute fee per ACI.
# We need to find applicable fee rule for each transaction given ACI choice.

def match_rule(rule, tx, aci_val):
    if rule['account_type'] and 'D' not in rule['account_type'] and rule['account_type']!=[]:
        return False
    if rule['account_type']==[] or rule['account_type'] is None:
        pass
    elif 'D' not in rule['account_type']:
        return False
    if rule.get('merchant_category_code') and rule['merchant_category_code']!=[]:
        if 7372 not in rule['merchant_category_code']:
            return False
    if rule.get('card_scheme') and rule['card_scheme']!=tx['card_scheme']:
        return False
    if rule.get('is_credit') is not None:
        if rule['is_credit'] != bool(tx['is_credit']):
            return False
    if rule.get('aci') and rule['aci']!=[]:
        if aci_val not in rule['aci']:
            return False
    if rule.get('capture_delay') is not None:
        cd = rule['capture_delay']
        # rafa capture_delay = '7' -> >5
        if cd=='>5':
            pass
        elif cd=='manual':
            return False
        elif cd=='immediate':
            return False
        elif cd=='<3':
            return False
        elif cd=='3-5':
            return False
    if rule.get('monthly_volume') is not None:
        mv = rule['monthly_volume']
        # rafa Oct volume 210k -> 100k-1m
        if mv != '100k-1m':
            return False
    if rule.get('monthly_fraud_level') is not None:
        mfl = rule['monthly_fraud_level']
        # ~10.6% - need to check which bucket. Let's see possible values
        # For now, if the fraud level rule exists, check if 10.6 falls in it
        # parse
        try:
            if '%-' in mfl:
                lo, hi = mfl.replace('%','').split('-')
                if not (float(lo) <= 10.6 <= float(hi)):
                    return False
            elif mfl.startswith('>'):
                if not (10.6 > float(mfl.replace('>','').replace('%',''))):
                    return False
            elif mfl.startswith('<'):
                if not (10.6 < float(mfl.replace('<','').replace('%',''))):
                    return False
        except:
            return False
    if rule.get('intracountry') is not None:
        intra = tx['issuing_country']==tx['acquirer_country']
        if bool(rule['intracountry']) != intra:
            return False
    return True

def compute_fee(tx, aci_val):
    best = None
    for rule in fees:
        if match_rule(rule, tx, aci_val):
            fee = rule['fixed_amount'] + rule['rate']*tx['eur_amount']/10000
            if best is None or fee < best:
                best = fee
    return best

# For each of 7 ACI values, sum total fee across fraud transactions
results = {}
for aci_val in ['A','B','C','D','E','F','G']:
    total = 0
    missing = 0
    for _, tx in fraud.iterrows():
        f = compute_fee(tx, aci_val)
        if f is None:
            missing += 1
        else:
            total += f
    results[aci_val] = (total, missing)

for k,v in results.items():
    print(k, v)
