import json, pandas as pd
fees = json.load(open('data/fees.json'))

mcc = 5942
acct = 'R'
# capture_delay '1' → the merchant record says '1'. Possible fee values: '3-5','>5','<3','immediate','manual'. 1 day is <3.
capture_delay_val = '<3'
monthly_volume = '100k-1m'  # 109853 → 100k-1m
# fraud ratio ~9.76% 
fraud_pct = 9.76

def match_range(rule_val, num):
    # rule_val like '7.7%-8.3%' or '>8.3%' etc.
    import re
    rv = rule_val.replace('%','').strip()
    if rv.startswith('>'):
        return num > float(rv[1:])
    if rv.startswith('<'):
        return num < float(rv[1:])
    if '-' in rv:
        a,b = rv.split('-')
        return float(a) <= num <= float(b)
    return False

def match_vol(rule_val, num):
    # e.g., '100k-1m', '>1m', '<100k'
    def parse(x):
        x = x.strip()
        if x.endswith('k'): return float(x[:-1])*1000
        if x.endswith('m'): return float(x[:-1])*1_000_000
        return float(x)
    rv = rule_val.strip()
    if rv.startswith('>'):
        return num > parse(rv[1:])
    if rv.startswith('<'):
        return num < parse(rv[1:])
    if '-' in rv:
        a,b = rv.split('-')
        return parse(a) <= num <= parse(b)
    return False

matching = []
for f in fees:
    # account_type
    if f['account_type'] and acct not in f['account_type']:
        continue
    # mcc
    if f['merchant_category_code'] and mcc not in f['merchant_category_code']:
        continue
    # capture_delay
    if f['capture_delay'] is not None and f['capture_delay'] != capture_delay_val:
        continue
    # monthly_volume
    if f['monthly_volume'] is not None and not match_vol(f['monthly_volume'], 109853.33):
        continue
    # monthly_fraud_level
    if f['monthly_fraud_level'] is not None and not match_range(f['monthly_fraud_level'], fraud_pct):
        continue
    matching.append(f['ID'])

print(len(matching), matching)
