python3 << 'EOF'
import json, pandas as pd
with open('data/fees.json') as f:
    fees = json.load(f)

# Merchant info
merchant = {'merchant': 'Golfclub_Baron_Friso', 'capture_delay': '2', 'acquirer': ['medici'], 'merchant_category_code': 7993, 'account_type': 'F'}

# Compute monthly volume & fraud level for month containing day 12 of 2023 (Jan 12)
p = pd.read_csv('data/payments.csv')
mp = p[(p['merchant']=='Golfclub_Baron_Friso') & (p['year']==2023)]
# Day 12 = Jan 12. Natural month = January (day_of_year 1-31)
jan = mp[(mp['day_of_year']>=1) & (mp['day_of_year']<=31)]
total_vol = jan['eur_amount'].sum()
fraud_vol = jan[jan['has_fraudulent_dispute']==True]['eur_amount'].sum()
fraud_ratio = fraud_vol/total_vol if total_vol>0 else 0
print("Total January volume:", total_vol, "Fraud ratio:", fraud_ratio)

# capture_delay '2' means 2 days - so falls in '<3'
cd = '<3'

def vol_match(rule, vol):
    r = rule['monthly_volume']
    if r is None: return True
    # parse e.g. '100k-1m', '>5m', '<100k'
    def parse(s):
        s = s.replace('k','e3').replace('m','e6')
        return float(s)
    if '-' in r:
        lo, hi = r.split('-')
        return parse(lo) <= vol < parse(hi)
    if r.startswith('>'):
        return vol > parse(r[1:])
    if r.startswith('<'):
        return vol < parse(r[1:])
    return True

def fraud_match(rule, fr):
    r = rule['monthly_fraud_level']
    if r is None: return True
    # e.g. '7.7%-8.3%'
    def parse(s):
        return float(s.replace('%',''))/100
    if '-' in r:
        lo,hi = r.split('-')
        return parse(lo) <= fr < parse(hi)
    if r.startswith('>'):
        return fr > parse(r[1:])
    if r.startswith('<'):
        return fr < parse(r[1:])
    return True

matches = []
for f in fees:
    # account_type
    if f['account_type'] and 'F' not in f['account_type']:
        continue
    # mcc
    if f['merchant_category_code'] and 7993 not in f['merchant_category_code']:
        continue
    # capture_delay
    if f['capture_delay'] is not None and f['capture_delay'] != cd:
        continue
    if not vol_match(f, total_vol):
        continue
    if not fraud_match(f, fraud_ratio):
        continue
    matches.append(f['ID'])

print(len(matches))
print(matches)
EOF

