python3 << 'EOF'
import pandas as pd, json
df = pd.read_csv('data/payments.csv')
df = df[df['merchant']=='Rafa_AI'].copy()
df = df[(df['day_of_year']>=182)&(df['day_of_year']<=212)]
fraud = df[df['has_fraudulent_dispute']==True].copy()
fees = json.load(open('data/fees.json'))

account_type = 'D'
mcc = 7372
cap = '>5'
mv = '100k-1m'
fl = '>8.3%'

def matches(rule, tx):
    if rule.get('account_type') and account_type not in rule['account_type']:
        return False
    if rule.get('merchant_category_code') and mcc not in rule['merchant_category_code']:
        return False
    if rule.get('capture_delay') is not None and rule['capture_delay'] != cap:
        return False
    if rule.get('monthly_volume') is not None and rule['monthly_volume'] != mv:
        return False
    if rule.get('monthly_fraud_level') is not None and rule['monthly_fraud_level'] != fl:
        return False
    if rule.get('is_credit') is not None and rule['is_credit'] != tx['is_credit']:
        return False
    if rule.get('card_scheme') and rule['card_scheme'] != tx['card_scheme']:
        return False
    if rule.get('aci') and tx['aci'] not in rule['aci']:
        return False
    if rule.get('intracountry') is not None:
        intra = tx['issuing_country'] == tx['acquirer_country']
        if rule['intracountry'] != intra:
            return False
    return True

def compute_fee(tx):
    matching = [r for r in fees if matches(r, tx)]
    if not matching:
        return None, []
    # take first? typically one match. Sum? Let's inspect
    total = 0
    for r in matching:
        total += r['fixed_amount'] + r['rate']*tx['eur_amount']/10000
    return total, matching

# For each ACI option A-G except G, compute the total fee for the fraud txns
acis = ['A','B','C','D','E','F','G']
results = {}
for aci in acis:
    total = 0
    missing = 0
    for _, row in fraud.iterrows():
        tx = {'is_credit': row['is_credit'], 'card_scheme': row['card_scheme'],
              'aci': aci, 'issuing_country': row['issuing_country'],
              'acquirer_country': row['acquirer_country'], 'eur_amount': row['eur_amount']}
        f, m = compute_fee(tx)
        if f is None:
            missing += 1
        else:
            total += f
    results[aci] = (total, missing)
    print(aci, round(total,2), "missing:", missing)
