import pandas as pd, json
df = pd.read_csv('data/payments.csv')
df = df[df['merchant']=='Rafa_AI'].copy()
df = df[(df['day_of_year']>=182)&(df['day_of_year']<=212)]
fraud = df[df['has_fraudulent_dispute']==True].copy()
fees = json.load(open('data/fees.json'))

account_type = 'D'
mcc = 7372
cap = '>5'
mv = '100k-1m'
fl = '>8.3%'

def matches(rule, tx):
    at = rule.get('account_type')
    if at and len(at)>0 and account_type not in at:
        return False
    mcc_list = rule.get('merchant_category_code')
    if mcc_list and len(mcc_list)>0 and mcc not in mcc_list:
        return False
    if rule.get('capture_delay') is not None and rule['capture_delay'] != cap:
        return False
    if rule.get('monthly_volume') is not None and rule['monthly_volume'] != mv:
        return False
    if rule.get('monthly_fraud_level') is not None and rule['monthly_fraud_level'] != fl:
        return False
    if rule.get('is_credit') is not None and rule['is_credit'] != tx['is_credit']:
        return False
    if rule.get('card_scheme') and rule['card_scheme'] != tx['card_scheme']:
        return False
    aci_list = rule.get('aci')
    if aci_list and len(aci_list)>0 and tx['aci'] not in aci_list:
        return False
    if rule.get('intracountry') is not None:
        intra = tx['issuing_country'] == tx['acquirer_country']
        rule_intra = bool(rule['intracountry'])
        if rule_intra != intra:
            return False
    return True

acis = ['A','B','C','D','E','F','G']
results = {}
for aci in acis:
    total = 0
    missing = 0
    match_counts = []
    for _, row in fraud.iterrows():
        tx = {'is_credit': row['is_credit'], 'card_scheme': row['card_scheme'],
              'aci': aci, 'issuing_country': row['issuing_country'],
              'acquirer_country': row['acquirer_country'], 'eur_amount': row['eur_amount']}
        m = [r for r in fees if matches(r, tx)]
        match_counts.append(len(m))
        if not m:
            missing += 1
        else:
            for r in m:
                total += r['fixed_amount'] + r['rate']*row['eur_amount']/10000
    print(aci, "total:", round(total,2), "missing:", missing, "avg matches:", sum(match_counts)/len(match_counts))
