python3 << 'EOF'
import pandas as pd, json
df = pd.read_csv('data/payments.csv')
m = df[(df['merchant']=='Martinis_Fine_Steakhouse') & (df['day_of_year']<=31)].copy()

with open('data/fees.json') as f:
    fees = json.load(f)

mcc = 5812
account_type = 'H'
capture_delay = 'immediate'
jan_vol = m['eur_amount'].sum()
fraud_vol = m[m['has_fraudulent_dispute']==True]['eur_amount'].sum()
fr_ratio = fraud_vol/jan_vol*100

def match_rule(rule, tx):
    if rule['card_scheme'] != tx['card_scheme']:
        return False
    if rule['account_type']:  # non-empty list
        if account_type not in rule['account_type']:
            return False
    if rule['capture_delay'] is not None:
        cd = rule['capture_delay']
        if cd == 'immediate':
            if capture_delay != 'immediate': return False
        elif cd == '<3':
            if capture_delay not in ['immediate','1','2']: return False
        elif cd == '3-5':
            if capture_delay not in ['3','4','5']: return False
        elif cd == '>5':
            try:
                if int(capture_delay) <= 5: return False
            except: return False
        elif cd == 'manual':
            if capture_delay != 'manual': return False
    if rule['monthly_fraud_level'] is not None:
        lvl = rule['monthly_fraud_level']
        if lvl.startswith('<'):
            if fr_ratio >= float(lvl[1:].replace('%','')): return False
        elif lvl.startswith('>'):
            if fr_ratio <= float(lvl[1:].replace('%','')): return False
        elif '-' in lvl:
            lo,hi = lvl.replace('%','').split('-')
            if not (float(lo) <= fr_ratio <= float(hi)): return False
    if rule['monthly_volume'] is not None:
        v = jan_vol
        mv = rule['monthly_volume']
        if mv == '100k-1m':
            if not (100000 <= v <= 1000000): return False
        elif mv == '1m-5m':
            if not (1000000 <= v <= 5000000): return False
        elif mv == '5m-10m':
            if not (5000000 <= v <= 10000000): return False
        elif mv.startswith('<'):
            thr = mv[1:]
            mult = 1000 if 'k' in thr else 1000000
            if v >= float(thr.replace('k','').replace('m',''))*mult: return False
        elif mv.startswith('>'):
            thr = mv[1:]
            mult = 1000 if 'k' in thr else 1000000
            if v <= float(thr.replace('k','').replace('m',''))*mult: return False
    if rule['merchant_category_code']:  # non-empty
        if mcc not in rule['merchant_category_code']:
            return False
    if rule['is_credit'] is not None:
        if rule['is_credit'] != tx['is_credit']: return False
    if rule['aci']:  # non-empty
        if tx['aci'] not in rule['aci']:
            return False
    if rule['intracountry'] is not None:
        intra = (tx['issuing_country'] == tx['acquirer_country'])
        if bool(rule['intracountry']) != intra: return False
    return True

def compute_fee(tx):
    matched = [r for r in fees if match_rule(r, tx)]
    if not matched:
        return None, 0
    # Take min? Or all? Or first? Typically most specific. Let's take min for now
    fees_list = [r['fixed_amount'] + r['rate']*tx['eur_amount']/10000 for r in matched]
    return min(fees_list), len(matched)

m['fee'], m['n'] = zip(*m.apply(compute_fee, axis=1))
print("Missing fees:", m['fee'].isna().sum())
print("Multi-match distribution:", m['n'].value_counts())
print("Fees by scheme (current):")
print(m.groupby('card_scheme')['fee'].sum())

# Simulate steering: all transactions to one scheme
for scheme in ['TransactPlus','GlobalCard','NexPay','SwiftCharge']:
    tmp = m.copy()
    tmp['card_scheme'] = scheme
    tmp['fee'], tmp['n'] = zip(*tmp.apply(compute_fee, axis=1))
    print(f"{scheme}: total={tmp['fee'].sum():.2f}, missing={tmp['fee'].isna().sum()}")
