monthly_vol = m['eur_amount'].sum()
fraud_rate = m[m['has_fraudulent_dispute']==True]['eur_amount'].sum()/monthly_vol*100

def parse_vol(s):
    s=s.replace('k','e3').replace('m','e6')
    return float(s)

def match(rule, tx, scheme):
    if rule['card_scheme'] != scheme: return False
    if rule['account_type'] and 'H' not in rule['account_type']: return False
    cd = rule['capture_delay']
    if cd is not None and cd != 'immediate' and cd != 'manual':
        # merchant is 'immediate', check against rule range
        # rule could be '3-5','>5','<3','immediate','manual'
        return False
    if rule['monthly_fraud_level'] is not None:
        lvl = rule['monthly_fraud_level'].replace('%','')
        if '-' in lvl:
            lo,hi=lvl.split('-'); 
            if not (float(lo)<=fraud_rate<=float(hi)): return False
        elif lvl.startswith('<'):
            if not fraud_rate<float(lvl[1:]): return False
        elif lvl.startswith('>'):
            if not fraud_rate>float(lvl[1:]): return False
    if rule['monthly_volume'] is not None:
        v = rule['monthly_volume']
        if '-' in v:
            lo,hi=v.split('-')
            if not (parse_vol(lo)<=monthly_vol<=parse_vol(hi)): return False
        elif v.startswith('<'):
            if not monthly_vol<parse_vol(v[1:]): return False
        elif v.startswith('>'):
            if not monthly_vol>parse_vol(v[1:]): return False
    if rule['merchant_category_code'] and 5812 not in rule['merchant_category_code']:
        return False
    if rule['is_credit'] is not None and rule['is_credit']!=tx['is_credit']:
        return False
    if rule['aci'] and tx['aci'] not in rule['aci']:
        return False
    if rule['intracountry'] is not None and bool(rule['intracountry'])!=bool(tx['intracountry']):
        return False
    return True

schemes = ['TransactPlus','NexPay','GlobalCard','SwiftCharge']
