vol=dec.eur_amount.sum(); fraud_ratio=dec[dec.has_fraudulent_dispute].eur_amount.sum()/vol*100
print('vol',vol,'fraud',fraud_ratio)
# distribution of scheme/aci/credit/intra for unmatched
def vm(r):
    rr=r['monthly_volume']
    if rr is None: return True
    def p(s): s=s.replace('k','000').replace('m','000000');return float(s)
    if '-' in rr: lo,hi=rr.split('-');return p(lo)<=vol<p(hi)
    if rr[0]=='>':return vol>p(rr[1:])
    if rr[0]=='<':return vol<p(rr[1:])
def fm(r):
    rr=r['monthly_fraud_level']
    if rr is None:return True
    def p(s):return float(s.replace('%',''))
    if '-' in rr:lo,hi=rr.split('-');return p(lo)<=fraud_ratio<p(hi)
    if rr[0]=='>':return fraud_ratio>p(rr[1:])
    if rr[0]=='<':return fraud_ratio<p(rr[1:])
def match(r,tx):
