        intra=tx['issuing_country']==tx['acquirer_country']
        if bool(r['intracountry'])!=intra:return False
    if not vm(r):return False
    if not fm(r):return False
    return True
for _,tx in dec.iterrows():
    if not [r for r in fees if match(r,tx)]:
        print(dict(scheme=tx['card_scheme'],credit=tx['is_credit'],aci=tx['aci'],iss=tx['issuing_country'],acq=tx['acquirer_country']))
        break
