monthly_vol = {int(k):v for k,v in mj['monthly_vol'].items()}
monthly_fraud = {int(k):v for k,v in mj['monthly_fraud'].items()}

account_type='H'
capture_delay='immediate'

def parse_range_vol(s):
    # returns (low, high) in euros
    def conv(x):
        x=x.strip()
        if x.endswith('k'): return float(x[:-1])*1e3
        if x.endswith('m'): return float(x[:-1])*1e6
        return float(x)
    if '-' in s:
        a,b=s.split('-'); return conv(a),conv(b)
    if s.startswith('>'): return conv(s[1:]), float('inf')
    if s.startswith('<'): return 0.0, conv(s[1:])
    return conv(s),conv(s)

def match_vol(rule_s, vol):
    if rule_s is None: return True
    lo,hi=parse_range_vol(rule_s)
    return lo<=vol<=hi  # boundaries inclusive per manual

def parse_pct(s):
    return float(s.strip().replace('%',''))/100

def match_fraud(rule_s, fr):
    if rule_s is None: return True
    if '-' in rule_s:
        a,b=rule_s.split('-'); return parse_pct(a)<=fr<=parse_pct(b)
    if rule_s.startswith('>'): return fr>parse_pct(rule_s[1:])
    if rule_s.startswith('<'): return fr<parse_pct(rule_s[1:])
    return fr==parse_pct(rule_s)

def match_capture(rule_s):
    if rule_s is None: return True
    return rule_s==capture_delay

def find_fee(row, mcc, vol, fr):
    intracountry = row['issuing_country']==row['acquirer_country']
    matches=[]
    for f in fees:
        if f['card_scheme'] is not None and f['card_scheme']!=row['card_scheme']: continue
        if f['account_type'] and account_type not in f['account_type']: continue
        if not match_capture(f['capture_delay']): continue
        if not match_fraud(f['monthly_fraud_level'], fr): continue
        if not match_vol(f['monthly_volume'], vol): continue
        if f['merchant_category_code'] and mcc not in f['merchant_category_code']: continue
        if f['is_credit'] is not None and f['is_credit']!=bool(row['is_credit']): continue
        if f['aci'] and row['aci'] not in f['aci']: continue
        if f['intracountry'] is not None and bool(f['intracountry'])!=intracountry: continue
        matches.append(f)
    if not matches: return None
    f=matches[0]
    return f['fixed_amount'] + f['rate']*row['eur_amount']/10000

def total_fees(mcc):
    tot=0.0
    for _,row in df.iterrows():
        vol=monthly_vol[row['month']]
        fr=monthly_fraud[row['month']]
        fee=find_fee(row,mcc,vol,fr)
        if fee is not None: tot+=fee
    return tot

