def in_range(val, rng):
    # rng like '100k-1m', '7.7%-8.3%', '>5','<3'
    def parse(s):
        s=s.replace('%','')
        s=s.replace('k','e3').replace('m','e6')
        return float(s)
    if rng is None: return True
    if '-' in rng:
        lo,hi = rng.split('-')
        return parse(lo)<=val<=parse(hi)
    if rng.startswith('>'):
        return val>parse(rng[1:])
    if rng.startswith('<'):
        return val<parse(rng[1:])
    if rng=='immediate' or rng=='manual':
        return False
    return parse(rng)==val

def matches(rule, tx, scheme):
    if rule['card_scheme']!=scheme: return False
    if rule['account_type'] and merch['account_type'] not in rule['account_type']: return False
    # capture_delay
