    if rule['merchant_category_code'] and merch['mcc'] not in rule['merchant_category_code']: return False
    if rule['is_credit'] is not None and rule['is_credit']!=tx['is_credit']: return False
    if rule['aci'] and tx['aci'] not in rule['aci']: return False
    if rule['intracountry'] is not None:
        intra = (tx['issuing_country']==tx['acquirer_country'])
        if rule['intracountry']!=intra: return False
    return True

schemes = ['GlobalCard','NexPay','SwiftCharge','TransactPlus']
