cd data && python3 << 'EOF'
import pandas as pd, json

df = pd.read_csv('payments.csv')
with open('fees.json') as f: fees = json.load(f)

merchant='Martinis_Fine_Steakhouse'
mcc=5812; acct='H'; capture_delay='immediate'
vol=96552.67; fraud_rate=9.816

def vol_match(rule):
    r=rule['monthly_volume']
    if r is None: return True
    def p(x): return float(x.replace('k','000').replace('m','000000'))
    if '-' in r:
        lo,hi=r.split('-'); return p(lo)<=vol<=p(hi)
    if r.startswith('<'): return vol<p(r[1:])
    if r.startswith('>'): return vol>p(r[1:])
def fraud_match(rule):
    r=rule['monthly_fraud_level']
    if r is None: return True
    if '-' in r:
        lo,hi=r.replace('%','').split('-'); return float(lo)<=fraud_rate<=float(hi)
    if r.startswith('<'): return fraud_rate<float(r[1:].replace('%',''))
    if r.startswith('>'): return fraud_rate>float(r[1:].replace('%',''))
def match(rule, tx):
    if rule['card_scheme'] is not None and rule['card_scheme']!=tx.card_scheme: return False
    if rule['account_type'] and acct not in rule['account_type']: return False
    if rule['capture_delay'] is not None and rule['capture_delay']!=capture_delay: return False
    if not fraud_match(rule): return False
    if not vol_match(rule): return False
    if rule['merchant_category_code'] and mcc not in rule['merchant_category_code']: return False
    if rule['is_credit'] is not None and rule['is_credit']!=bool(tx.is_credit): return False
    if rule['aci'] and tx.aci not in rule['aci']: return False
    if rule['intracountry'] is not None:
        intra = (tx.issuing_country==tx.acquirer_country)
        if bool(rule['intracountry'])!=intra: return False
    return True

tx = df[(df.merchant==merchant)&(df.year==2023)&(df.day_of_year==365)]
for _,t in tx.iterrows():
    matched=[r for r in fees if match(r,t)]
    if not matched:
        # relax constraints one at a time to find culprit
        print(t.card_scheme, t.is_credit, t.aci, t.issuing_country==t.acquirer_country)
