df=pd.read_csv('data/payments.csv')
fees=json.load(open('data/fees.json'))

merchant={'capture_delay':'immediate','mcc':5812,'account_type':'H'}
monthly_volume=109430.93
fraud_rate=0.0873248541340186  # 8.73%

m=df[df['merchant']=='Martinis_Fine_Steakhouse']
sep=m[(m['day_of_year']>=244)&(m['day_of_year']<=273)].copy()

def vol_match(rule):
    r=rule['monthly_volume']
    if r is None: return True
    v=monthly_volume
    import re
    def parse(x):
        x=x.replace('k','000').replace('m','000000')
        return float(x)
    if r.startswith('>'):
        return v>parse(r[1:])
    if r.startswith('<'):
        return v<parse(r[1:])
    lo,hi=r.split('-')
    return parse(lo)<=v<=parse(hi)

def fraud_match(rule):
    r=rule['monthly_fraud_level']
    if r is None: return True
    fr=fraud_rate*100
    if r.startswith('>'):
        return fr>float(r[1:].replace('%',''))
    if r.startswith('<'):
        return fr<float(r[1:].replace('%',''))
    lo,hi=r.split('-')
    return float(lo.replace('%',''))<=fr<=float(hi.replace('%',''))

def match(rule,row,scheme):
    if rule['card_scheme']!=scheme: return False
    if rule['account_type'] and merchant['account_type'] not in rule['account_type']: return False
    if rule['capture_delay'] is not None and rule['capture_delay']!=merchant['capture_delay']: return False
    if rule['merchant_category_code'] and merchant['mcc'] not in rule['merchant_category_code']: return False
    if rule['is_credit'] is not None and rule['is_credit']!=bool(row['is_credit']): return False
    if rule['aci'] and row['aci'] not in rule['aci']: return False
    if not vol_match(rule): return False
    if not fraud_match(rule): return False
    if rule['intracountry'] is not None:
        intra=(row['issuing_country']==row['acquirer_country'])
        if rule['intracountry']!=intra: return False
    return True

schemes=['GlobalCard','NexPay','TransactPlus','SwiftCharge']
results={}
for scheme in schemes:
    total=0
    for _,row in sep.iterrows():
        matched=[r for r in fees if match(r,row,scheme)]
        if not matched:
            continue
        rule=matched[0]
        fee=rule['fixed_amount']+rule['rate']*row['eur_amount']/10000
        total+=fee
    results[scheme]=total

for s,t in sorted(results.items(),key=lambda x:x[1]):
    print(s, round(t,2))
