import json, pandas as pd

df = pd.read_csv('payments.csv')
fees = json.load(open('fees.json'))
merchants = {m['merchant']: m for m in json.load(open('merchant_data.json'))}

merch = 'Belles_cookbook_store'
m = merchants[merch]
sub = df[(df['merchant']==merch)&(df['year']==2023)]
print(len(sub))

fee276 = next(f for f in fees if f['ID']==276)

def matches(fee, row, m):
    if fee['card_scheme'] is not None and fee['card_scheme']!=row['card_scheme']:
        return False
    if fee['account_type'] and m['account_type'] not in fee['account_type']:
        return False
    if fee['is_credit'] is not None and fee['is_credit']!=row['is_credit']:
        return False
    if fee['aci'] and row['aci'] not in fee['aci']:
        return False
    if fee['merchant_category_code'] and m['merchant_category_code'] not in fee['merchant_category_code']:
        return False
    # capture_delay
    if fee['capture_delay'] is not None:
        cd=m['capture_delay']
        # matching logic
        fcd=fee['capture_delay']
        # m capture_delay '1'
        try: cdv=int(cd)
        except: cdv=None
        if fcd=='immediate':
            if not (cdv is not None and cdv==0): return False
        elif fcd=='manual':
            if cd!='manual': return False
        elif fcd=='<3':
            if not (cdv is not None and cdv<3): return False
        elif fcd=='>5':
            if not (cdv is not None and cdv>5): return False
        elif fcd=='3-5':
            if not (cdv is not None and 3<=cdv<=5): return False
    if fee['intracountry'] is not None:
        intra = row['issuing_country']==row['acquirer_country']
        if fee['intracountry']!=intra: return False
    # monthly_fraud_level, monthly_volume: None here
    return True

# Only rows matching fee 276
def compute(rate):
    total=0
    for _,row in sub.iterrows():
        if matches(fee276,row,m):
            total += fee276['fixed_amount'] + rate*row['eur_amount']/10000
    return total

orig = compute(fee276['rate'])
new = compute(99)
print("delta", new-orig)
print(round(new-orig,14))
