def doy_to_month(d): return datetime.strptime(f"2023-{d}","%Y-%j").month
mdf=df[df.merchant==merch].copy(); mdf['month']=mdf['day_of_year'].apply(doy_to_month)
sep=mdf[mdf.month==9].copy()
monthly_volume=sep['eur_amount'].sum()
fraud_level=sep[sep.has_fraudulent_dispute==True]['eur_amount'].sum()/monthly_volume*100
print("vol",monthly_volume,"fraud",fraud_level)

row=sep.iloc[0]
print(dict(row[['card_scheme','is_credit','aci','issuing_country','acquirer_country']]))
def cap_match(rcd,cd):
    cdv=1.0
    if rcd=='immediate': return False
    if rcd=='manual': return False
    if rcd=='<3': return cdv<3
    if rcd=='>5': return cdv>5
    if rcd=='3-5': return 3<=cdv<=5
    return False
cnt={}
for r in fees:
    reasons=[]
    if r['card_scheme'] and r['card_scheme']!=row['card_scheme']: reasons.append('scheme')
    if r['account_type'] and md['account_type'] not in r['account_type']: reasons.append('acct')
    if r['capture_delay'] is not None and not cap_match(r['capture_delay'],'1'): reasons.append('cap')
    def fm(rf,f):
        if rf is None: return True
        s=rf.replace('%','')
        if '-' in s: lo,hi=s.split('-'); return float(lo)<=f<float(hi)
        if s[0]=='>': return f>float(s[1:])
        if s[0]=='<': return f<float(s[1:])
    if not fm(r['monthly_fraud_level'],fraud_level): reasons.append('fraud')
    def vm(rv,v):
        if rv is None: return True
        def p(x): return float(x.replace('k','000').replace('m','000000'))
        if '-' in rv: lo,hi=rv.split('-'); return p(lo)<=v<p(hi)
        if rv[0]=='>': return v>p(rv[1:])
        if rv[0]=='<': return v<p(rv[1:])
    if not vm(r['monthly_volume'],monthly_volume): reasons.append('vol')
    if r['merchant_category_code'] and md['merchant_category_code'] not in r['merchant_category_code']: reasons.append('mcc')
    if r['is_credit'] is not None and r['is_credit']!=bool(row['is_credit']): reasons.append('credit')
    if r['aci'] and row['aci'] not in r['aci']: reasons.append('aci')
    if r['intracountry'] is not None and r['intracountry']!=(row['issuing_country']==row['acquirer_country']): reasons.append('intra')
    if not reasons:
        cnt.setdefault('MATCH',0); cnt['MATCH']+=1
# count single-reason failures across all rules
from collections import Counter
print("matches for row0:", cnt)
