arguments.command:
python3 << 'EOF'
import pandas as pd, json, collections
df = pd.read_csv('data/payments.csv')
df = df[df['merchant']=='Crossfit_Hanna']
df = df[(df['year']==2023) & (df['day_of_year']>=335) & (df['day_of_year']<=365)].copy()
with open('data/fees.json') as f: fees = json.load(f)
merchants = pd.read_json('data/merchant_data.json')
m = merchants[merchants['merchant']=='Crossfit_Hanna'].iloc[0]
mcc, acct, cap_delay = m['merchant_category_code'], m['account_type'], m['capture_delay']
monthly_volume = df['eur_amount'].sum()
fraud_rate = df[df['has_fraudulent_dispute']==True]['eur_amount'].sum()/monthly_volume

def mv(r,v):
    if r is None: return True
    def p(s): return float(s.replace('k','e3').replace('m','e6'))
    if '-' in r:
        lo,hi=r.split('-'); return p(lo)<=v<p(hi)
    if r.startswith('<'): return v<p(r[1:])
    if r.startswith('>'): return v>p(r[1:])
def mf(r,f):
    if r is None: return True
    r=r.replace('%','')
    fp=f*100
    if '-' in r:
        lo,hi=r.split('-'); return float(lo)<=fp<float(hi)
    if r.startswith('<'): return fp<float(r[1:])
    if r.startswith('>'): return fp>float(r[1:])

def find_matches(tx):
    matches=[]
    for rule in fees:
        if rule['card_scheme'] != tx['card_scheme']: continue
        if rule['account_type'] and acct not in rule['account_type']: continue
        if rule['merchant_category_code'] and mcc not in rule['merchant_category_code']: continue
        if rule['is_credit'] is not None and rule['is_credit'] != tx['is_credit']: continue
        if rule['aci'] and tx['aci'] not in rule['aci']: continue
        if rule['capture_delay'] is not None and rule['capture_delay'] != cap_delay: continue
        if rule['monthly_volume'] is not None and not mv(rule['monthly_volume'], monthly_volume): continue
        if rule['monthly_fraud_level'] is not None and not mf(rule['monthly_fraud_level'], fraud_rate): continue
        if rule['intracountry'] is not None:
            intra = tx['issuing_country'] == tx['acquirer_country']
            if bool(rule['intracountry']) != intra: continue
        matches.append(rule)
    return matches

# Look at breakdown by cardscheme/aci/is_credit for unmatched
unmatched_key = collections.Counter()
for _,tx in df.iterrows():
    if len(find_matches(tx))==0:
        unmatched_key[(tx['card_scheme'],tx['aci'],tx['is_credit'])]+=1
for k,v in unmatched_key.most_common():
    print(k, v)
