python3 << 'EOF'
import pandas as pd, json
p = pd.read_csv('data/payments.csv')
fees = json.load(open('data/fees.json'))

merch = 'Golfclub_Baron_Friso'
merchant_info = {'merchant': 'Golfclub_Baron_Friso', 'capture_delay': '2', 'acquirer': ['medici'], 'merchant_category_code': 7993, 'account_type': 'F'}

df = p[(p['merchant']==merch) & (p['year']==2023)].copy()
print('rows', len(df))

# Determine intracountry field per transaction
df['intracountry'] = (df['issuing_country']==df['acquirer_country'])

# For each fee rule, we need to match. Function to match rule to txn.
def matches(rule, txn, minfo):
    if rule['card_scheme'] != txn['card_scheme']:
        return False
    if rule['account_type'] and minfo['account_type'] not in rule['account_type']:
        return False
    # capture_delay - merchant '2' means less than 3? '2' days
    if rule['capture_delay'] is not None:
        cd = rule['capture_delay']
        mcd = minfo['capture_delay']
        # mcd '2' -> numeric 2
        try:
            mcd_num = int(mcd)
        except:
            mcd_num = None
        if cd == 'manual':
            if mcd != 'manual': return False
        elif cd == 'immediate':
            if mcd_num != 0: return False
        elif cd == '<3':
            if mcd_num is None or mcd_num >= 3: return False
        elif cd == '3-5':
            if mcd_num is None or not (3<=mcd_num<=5): return False
        elif cd == '>5':
            if mcd_num is None or mcd_num <=5: return False
    # monthly_fraud_level, monthly_volume - null in rule means any; skipping strict check for merchant since not given
    if rule['monthly_fraud_level'] is not None:
        return False  # merchant data doesn't specify - assume no match unless null
    if rule['monthly_volume'] is not None:
        return False
    if rule['merchant_category_code'] and minfo['merchant_category_code'] not in rule['merchant_category_code']:
        return False
    if rule['is_credit'] is not None:
        if bool(rule['is_credit']) != bool(txn['is_credit']):
            return False
    if rule['aci'] and txn['aci'] not in rule['aci']:
        return False
    if rule['intracountry'] is not None:
        if bool(rule['intracountry']) != bool(txn['intracountry']):
            return False
    return True

# For each transaction find matching rule
def find_fee(txn, minfo, fees):
    for rule in fees:
        if matches(rule, txn, minfo):
            return rule
    return None

# compute for each txn: fee under original 595 rate=62 and under new rate=1 if rule 595 applies
total_delta = 0.0
count_595 = 0
for _, txn in df.iterrows():
    rule = find_fee(txn, merchant_info, fees)
    if rule is None:
        continue
    if rule['ID']==595:
        count_595 += 1
        old_fee = rule['fixed_amount'] + rule['rate']*txn['eur_amount']/10000
        new_fee = rule['fixed_amount'] + 1*txn['eur_amount']/10000
        total_delta += (new_fee - old_fee)

print('count_595', count_595)
print('delta', total_delta)
print(f'{total_delta:.14f}')
