python3 << 'EOF'
import pandas as pd, json, datetime
df = pd.read_csv('data/payments.csv')
d1 = datetime.date(2023,7,1).timetuple().tm_yday
d2 = datetime.date(2023,7,31).timetuple().tm_yday
sub = df[(df.merchant=='Crossfit_Hanna') & (df.year==2023) & (df.day_of_year>=d1) & (df.day_of_year<=d2)]
fraud = sub[sub.has_fraudulent_dispute==True].copy()

with open('data/fees.json') as f:
    fees = json.load(f)

# Merchant info: Crossfit_Hanna: capture_delay='manual', mcc=7997, account_type='F'
merchant_mcc = 7997
account_type = 'F'
capture_delay = 'manual'

# monthly volume (July) and fraud level for July
july_vol = sub.eur_amount.sum()
july_fraud_vol = fraud.eur_amount.sum()
fraud_ratio = july_fraud_vol/july_vol*100
print('July vol:', july_vol, 'fraud vol:', july_fraud_vol, 'ratio %:', fraud_ratio)

# Compute intracountry per txn
fraud['intracountry'] = (fraud.issuing_country == fraud.acquirer_country)

def match_rule(rule, txn, aci_val):
    if rule['card_scheme'] != txn['card_scheme']: return False
    if rule['account_type'] and account_type not in rule['account_type']: return False
    if rule['capture_delay'] is not None and rule['capture_delay'] != capture_delay: return False
    if rule['merchant_category_code'] and merchant_mcc not in rule['merchant_category_code']: return False
    if rule['is_credit'] is not None and rule['is_credit'] != bool(txn['is_credit']): return False
    if rule['aci'] and aci_val not in rule['aci']: return False
    if rule['intracountry'] is not None and bool(rule['intracountry']) != bool(txn['intracountry']): return False
    # monthly_fraud_level
    if rule['monthly_fraud_level'] is not None:
        # skipping since we don't know exactly the ranges but let's evaluate
        s = rule['monthly_fraud_level']
        if not check_range(s, fraud_ratio): return False
    if rule['monthly_volume'] is not None:
        s = rule['monthly_volume']
        if not check_vol(s, july_vol): return False
    return True

def check_range(s, val):
    # forms like '7.7%-8.3%'
    s = s.replace('%','')
    if '-' in s:
        lo,hi = s.split('-')
        return float(lo) <= val <= float(hi)
    if s.startswith('<'):
        return val < float(s[1:])
    if s.startswith('>'):
        return val > float(s[1:])
    return False

def parse_vol(v):
    v = v.replace('k','e3').replace('m','e6')
    return float(v)

def check_vol(s, val):
    if '-' in s:
        lo,hi = s.split('-')
        return parse_vol(lo) <= val <= parse_vol(hi)
    if s.startswith('<'):
        return val < parse_vol(s[1:])
    if s.startswith('>'):
        return val > parse_vol(s[1:])
    return False

# For each candidate ACI, compute total fees for the fraudulent txns
acis = ['A','B','C','D','E','F','G']
totals = {}
for aci in acis:
    tot = 0
    unmatched = 0
    for _,txn in fraud.iterrows():
        matched = None
        for rule in fees:
            if match_rule(rule, txn, aci):
                matched = rule
                break
        if matched is None:
            unmatched += 1
            continue
        fee = matched['fixed_amount'] + matched['rate']*txn['eur_amount']/10000
        tot += fee
    totals[aci] = (tot, unmatched)
print(totals)
