python3 << 'EOF'
import pandas as pd, json
fees = json.load(open('data/fees.json'))
p = pd.read_csv('data/payments.csv')
p = p[(p['merchant']=='Golfclub_Baron_Friso') & (p['year']==2023)].copy()

merchant = {'account_type':'F','mcc':7993,'capture_delay':'2'}
# Compute for each transaction, find matching fee rule per card_scheme(actual)
# Question: which card scheme to steer to maximize fees. So we simulate: if all traffic goes to a scheme, what's total fee?

def match(rule, tx, scheme):
    if rule['card_scheme'] != scheme: return False
    if rule['account_type'] and 'F' not in rule['account_type']: return False
    if rule['merchant_category_code'] and 7993 not in rule['merchant_category_code']: return False
    if rule['capture_delay'] is not None:
        cd = rule['capture_delay']
        # merchant capture_delay = '2' => <3
        # capture delay '2' meaning 2 days
        if cd == '<3':
            pass  # matches since 2<3
        elif cd == '>5':
            return False
        elif cd == '3-5':
            return False
        elif cd == 'immediate':
            return False
        elif cd == 'manual':
            return False
    if rule['monthly_fraud_level'] is not None:
        return False  # no info; skip - but need to check merchant fraud
    if rule['monthly_volume'] is not None:
        return False
    if rule['is_credit'] is not None and rule['is_credit'] != tx['is_credit']:
        return False
    if rule['aci'] and tx['aci'] not in rule['aci']:
        return False
    if rule['intracountry'] is not None:
        intra = (tx['issuing_country'] == tx['acquirer_country'])
        if rule['intracountry'] != intra:
            return False
    return True

# First check fraud level and volume - we probably need to consider these
# monthly volume: total 2023 volume 
total_vol = p['eur_amount'].sum()
print('total volume 2023', total_vol)
# monthly average
print('monthly avg', total_vol/12)
