python3 << 'EOF'
import pandas as pd, json
merchants = json.load(open('data/merchant_data.json'))
m = [x for x in merchants if x['merchant']=='Martinis_Fine_Steakhouse'][0]
fees = json.load(open('data/fees.json'))
df = pd.read_csv('data/payments.csv')
sub = df[(df.merchant=='Martinis_Fine_Steakhouse')&(df.year==2023)].copy()

# For monthly volume/fraud calculations - compute per month
# Use day_of_year to compute month
sub['date'] = pd.to_datetime(sub['year'].astype(str)) + pd.to_timedelta(sub['day_of_year']-1, unit='D')
sub['month'] = sub['date'].dt.month
monthly_vol = sub.groupby('month')['eur_amount'].sum()
monthly_fraud = sub[sub.has_fraudulent_dispute].groupby('month')['eur_amount'].sum()
monthly_fraud_ratio = (monthly_fraud/monthly_vol).fillna(0)
print("monthly volumes:", monthly_vol.to_dict())
print("monthly fraud ratio:", monthly_fraud_ratio.to_dict())

# Acquirer country -> the merchant has acquirers; intracountry is when issuing==acquirer
# Merchant properties
mcc = m['merchant_category_code']
acct = m['account_type']
capture = m['capture_delay']

def match_fee(tx, fee, monthly_vol_val, monthly_fraud_val):
    if fee['card_scheme'] != tx['card_scheme']:
        return False
    if fee['account_type'] and acct not in fee['account_type']:
        return False
    if fee['capture_delay'] is not None:
        cd = fee['capture_delay']
        # capture is 'immediate'
        if cd == 'immediate':
            if capture != 'immediate': return False
        elif cd == 'manual':
            if capture != 'manual': return False
        elif cd == '<3':
            if capture not in ['immediate','1','2']: 
                try:
                    if int(capture)>=3: return False
                except: 
                    if capture!='immediate': return False
        elif cd == '3-5':
            try:
                if not (3<=int(capture)<=5): return False
            except: return False
        elif cd == '>5':
            try:
                if int(capture)<=5: return False
            except: return False
    if fee['monthly_fraud_level'] is not None:
        # parse like '7.7%-8.3%'
        s = fee['monthly_fraud_level'].replace('%','')
        lo,hi = s.split('-')
        lo=float(lo)/100; hi=float(hi)/100
        if not (lo <= monthly_fraud_val <= hi):
            return False
    if fee['monthly_volume'] is not None:
        s = fee['monthly_volume']
        def parse(x):
            x=x.strip()
            if x.endswith('k'): return float(x[:-1])*1000
            if x.endswith('m'): return float(x[:-1])*1_000_000
            return float(x)
        lo,hi = s.split('-')
        lo=parse(lo); hi=parse(hi)
        if not (lo <= monthly_vol_val <= hi):
            return False
    if fee['merchant_category_code'] and mcc not in fee['merchant_category_code']:
        return False
    if fee['is_credit'] is not None:
        if bool(fee['is_credit']) != bool(tx['is_credit']):
            return False
    if fee['aci'] and tx['aci'] not in fee['aci']:
        return False
    if fee['intracountry'] is not None:
        intra = (tx['issuing_country']==tx['acquirer_country'])
        if bool(fee['intracountry']) != intra:
            return False
    return True

total = 0.0
unmatched = 0
for _, tx in sub.iterrows():
    mvol = monthly_vol[tx['month']]
    mfraud = monthly_fraud_ratio[tx['month']]
    matched = None
    for f in fees:
        if match_fee(tx, f, mvol, mfraud):
            matched = f
            break
    if matched is None:
        unmatched += 1
        continue
    fee_val = matched['fixed_amount'] + matched['rate']*tx['eur_amount']/10000
    total += fee_val

print(f"total: {total:.2f}, unmatched: {unmatched}")
