python3 << 'EOF'
import pandas as pd, json
df = pd.read_csv('data/payments.csv')
with open('data/fees.json') as f: fees = json.load(f)
with open('data/merchant_data.json') as f: mdata = json.load(f)

merch = {'merchant': 'Belles_cookbook_store', 'capture_delay': '1', 'account_type': 'R', 'mcc': 5942, 'acquirer_country':'US'}
monthly_volume = 107343.79
monthly_fraud_ratio = 0.09145810856873976 * 100  # in %

def parse_range(rng, val):
    # ranges like '7.7%-8.3%' or '100k-1m' or '<3' or '>5' or 'immediate' or 'manual'
    if rng is None: return True
    s = rng
    if s.endswith('%'):
        s = s.replace('%','')
    def num(x):
        x = x.strip().lower()
        if x.endswith('k'): return float(x[:-1])*1000
        if x.endswith('m'): return float(x[:-1])*1_000_000
        return float(x)
    if '-' in s and not s.startswith('-'):
        a,b = s.split('-')
        return num(a) <= val <= num(b)
    if s.startswith('<'):
        return val < num(s[1:])
    if s.startswith('>'):
        return val > num(s[1:])
    return False

def capture_match(rule_cd, merch_cd):
    if rule_cd is None: return True
    # merchant capture_delay is '1' (means 1 day)
    try: mv = int(merch_cd)
    except: 
        if rule_cd == merch_cd: return True
        return False
    if rule_cd == 'immediate': return mv == 0
    if rule_cd == 'manual': return False
    if rule_cd.startswith('<'): return mv < int(rule_cd[1:])
    if rule_cd.startswith('>'): return mv > int(rule_cd[1:])
    if '-' in rule_cd:
        a,b = rule_cd.split('-'); return int(a)<=mv<=int(b)
    return False

def match_rule(rule, txn):
    if rule['card_scheme'] != txn['card_scheme']: return False
    if rule['account_type'] and merch['account_type'] not in rule['account_type']: return False
    if rule['merchant_category_code'] and merch['mcc'] not in rule['merchant_category_code']: return False
    if not capture_match(rule['capture_delay'], merch['capture_delay']): return False
    if rule['monthly_fraud_level'] is not None:
        if not parse_range(rule['monthly_fraud_level'], monthly_fraud_ratio): return False
    if rule['monthly_volume'] is not None:
        if not parse_range(rule['monthly_volume'], monthly_volume): return False
    if rule['is_credit'] is not None:
        if rule['is_credit'] != txn['is_credit']: return False
    if rule['aci'] and txn['aci'] not in rule['aci']: return False
    if rule['intracountry'] is not None:
        intra = (txn['issuing_country'] == txn['acquirer_country'])
        if bool(rule['intracountry']) != intra: return False
    return True

# For day 100 transactions
day100 = df[(df.merchant=='Belles_cookbook_store') & (df.year==2023) & (df.day_of_year==100)]
total_fee = 0.0
for _, t in day100.iterrows():
    txn = {'card_scheme': t.card_scheme, 'is_credit': bool(t.is_credit), 'aci': t.aci,
           'issuing_country': t.issuing_country, 'acquirer_country': t.acquirer_country}
    matches = [r for r in fees if match_rule(r, txn)]
    if len(matches) != 1:
        # pick most specific? Let's just check
        pass
    if not matches:
        print("NO MATCH:", txn)
        continue
    # If multiple, use first (or most specific). Let's take the one with most non-null fields
    def specificity(r):
        return sum(1 for k in ['account_type','capture_delay','monthly_fraud_level','monthly_volume','merchant_category_code','is_credit','aci','intracountry'] if r[k] not in (None, []))
    matches.sort(key=specificity, reverse=True)
    r = matches[0]
    fee = r['fixed_amount'] + r['rate'] * t.eur_amount / 10000
    total_fee += fee

print("Total fees:", round(total_fee,2))
