fees = json.load(open('data/fees.json'))
merchants = json.load(open('data/merchant_data.json'))
info = [m for m in merchants if m['merchant']=='Belles_cookbook_store'][0]
mcc, acct, capture = info['merchant_category_code'], info['account_type'], info['capture_delay']

dec_vol = belles.eur_amount.sum()
dec_fraud = belles[belles.has_fraudulent_dispute==True].eur_amount.sum()
fraud_rate = dec_fraud/dec_vol*100

def parse_range(rng, val):
    if rng is None: return True
    def num(x):
        x = x.replace('%','')
        if x.endswith('k'): return float(x[:-1])*1000
        if x.endswith('m'): return float(x[:-1])*1_000_000
        return float(x)
    if rng.startswith('<'): return val < num(rng[1:])
    if rng.startswith('>'): return val > num(rng[1:])
    if '-' in rng:
        lo,hi = rng.split('-')
        return num(lo) <= val <= num(hi)
    return False

def match_fee(row, rule):
    if rule['card_scheme'] != row['card_scheme']: return False
    if rule['account_type'] and acct not in rule['account_type']: return False
    cd = rule['capture_delay']
    if cd is not None:
        try: cap_val = int(capture)
        except: cap_val = None
        if cd == 'manual':
            if capture != 'manual': return False
        elif cd == 'immediate':
            if capture != 'immediate': return False
        elif cd.startswith('<'):
            if cap_val is None or not (cap_val < int(cd[1:])): return False
        elif cd.startswith('>'):
            if cap_val is None or not (cap_val > int(cd[1:])): return False
        elif '-' in cd:
            lo,hi = cd.split('-')
            if cap_val is None or not (int(lo) <= cap_val <= int(hi)): return False
    if rule['monthly_fraud_level'] is not None:
        if not parse_range(rule['monthly_fraud_level'], fraud_rate): return False
    if rule['monthly_volume'] is not None:
        if not parse_range(rule['monthly_volume'], dec_vol): return False
    if rule['merchant_category_code'] and mcc not in rule['merchant_category_code']: return False
    if rule['is_credit'] is not None:
        if rule['is_credit'] != bool(row['is_credit']): return False
    if rule['aci'] and row['aci'] not in rule['aci']: return False
    if rule['intracountry'] is not None:
        intra = (row['issuing_country'] == row['acquirer_country'])
        want = bool(rule['intracountry'])
        if want != intra: return False
    return True

# check unmatched row characteristics
unmatched_key = []
for _, row in belles.iterrows():
    matched = [r for r in fees if match_fee(row, r)]
    if len(matched)==0:
        unmatched_key.append((row['card_scheme'], row['is_credit'], row['aci'], row['issuing_country']==row['acquirer_country']))
from collections import Counter
print(Counter(unmatched_key).most_common(20))
