        return num(lo) <= val <= num(hi)
    return False

def match_fee(row, rule):
    if rule['card_scheme'] != row['card_scheme']: return False
    if rule['account_type'] and acct not in rule['account_type']: return False
    cd = rule['capture_delay']
    if cd is not None:
        try: cap_val = int(capture)
        except: cap_val = None
        if cd == 'manual':
            if capture != 'manual': return False
        elif cd == 'immediate':
            if capture != 'immediate': return False
        elif cd.startswith('<'):
            if cap_val is None or not (cap_val < int(cd[1:])): return False
        elif cd.startswith('>'):
            if cap_val is None or not (cap_val > int(cd[1:])): return False
        elif '-' in cd:
            lo,hi = cd.split('-')
            if cap_val is None or not (int(lo) <= cap_val <= int(hi)): return False
    if rule['monthly_fraud_level'] is not None:
        if not parse_range(rule['monthly_fraud_level'], fraud_rate): return False
    if rule['monthly_volume'] is not None:
        if not parse_range(rule['monthly_volume'], dec_vol): return False
    if rule['merchant_category_code'] and mcc not in rule['merchant_category_code']: return False
