        intra = (row['issuing_country'] == row['acquirer_country'])
        want = bool(rule['intracountry'])
        if want != intra: return False
    return True

def specificity(rule):
    s = 0
    for k in ['account_type','capture_delay','monthly_fraud_level','monthly_volume','merchant_category_code','is_credit','aci','intracountry']:
        v = rule[k]
        if v is None or v==[]: pass
        else: s += 1
    return s

