import pandas as pd, json
df = pd.read_csv('data/payments.csv')
fees = json.load(open('data/fees.json'))
merchants = json.load(open('data/merchant_data.json'))
m_info = [x for x in merchants if x['merchant']=='Martinis_Fine_Steakhouse'][0]

txns = df[(df['merchant']=='Martinis_Fine_Steakhouse') & (df['year']==2023)].copy()
txns['intracountry'] = (txns['issuing_country'] == txns['acquirer_country']).astype(bool)
txns['date'] = pd.to_datetime(txns['year'].astype(str), format='%Y') + pd.to_timedelta(txns['day_of_year']-1, unit='D')
txns['month'] = txns['date'].dt.month

monthly_vol = txns.groupby('month')['eur_amount'].sum().to_dict()
monthly_fraud = txns[txns['has_fraudulent_dispute']==True].groupby('month')['eur_amount'].sum().to_dict()
monthly_fraud_ratio = {m: (monthly_fraud.get(m,0)/monthly_vol[m])*100 for m in monthly_vol}
print("monthly vols:", monthly_vol)
print("monthly fraud ratios:", monthly_fraud_ratio)

def parse_range(s, val):
    def conv(x):
        x = x.strip().replace('%','')
        if x.endswith('k'): return float(x[:-1])*1e3
        if x.endswith('m'): return float(x[:-1])*1e6
        return float(x)
    if s is None: return True
    s = s.strip()
    if s.startswith('>'):
        return val > conv(s[1:])
    if s.startswith('<'):
        return val < conv(s[1:])
    if '-' in s:
        a,b = s.split('-')
        return conv(a) <= val <= conv(b)
    return True

def match(rule, tx, mcc):
    if rule['card_scheme'] != tx['card_scheme']: return False
    if rule['account_type'] and m_info['account_type'] not in rule['account_type']: return False
    if rule['capture_delay'] is not None:
        # match against merchant's capture_delay 'immediate'
        cd = m_info['capture_delay']
        r = rule['capture_delay']
        if r != cd:
            # check ranges: 'immediate' merchant only matches 'immediate' rule
            return False
    if rule['monthly_fraud_level'] is not None:
        if not parse_range(rule['monthly_fraud_level'], monthly_fraud_ratio[tx['month']]): return False
    if rule['monthly_volume'] is not None:
        if not parse_range(rule['monthly_volume'], monthly_vol[tx['month']]): return False
    if rule['merchant_category_code'] and mcc not in rule['merchant_category_code']: return False
    if rule['is_credit'] is not None and rule['is_credit'] != tx['is_credit']: return False
    if rule['aci'] and tx['aci'] not in rule['aci']: return False
    if rule['intracountry'] is not None and bool(rule['intracountry']) != bool(tx['intracountry']): return False
    return True

# check unmatched
sample_tx = None
for tx in txns.to_dict('records'):
