    unmatched = 0
    for tx in txns.to_dict('records'):
        matches = [r for r in fees if match(r, tx, mcc)]
        if not matches:
            unmatched += 1
            continue
        if mode=='sum':
            for r in matches:
                total += r['fixed_amount'] + r['rate']*tx['eur_amount']/10000
        elif mode=='avg':
            total += sum(r['fixed_amount'] + r['rate']*tx['eur_amount']/10000 for r in matches)/len(matches)
        elif mode=='first':
            r = matches[0]
            total += r['fixed_amount'] + r['rate']*tx['eur_amount']/10000
    return total, unmatched

