python3 << 'EOF'
import json, pandas as pd

df = pd.read_csv('data/payments.csv')
d = pd.to_datetime(df['year'].astype(str) + '-' + df['day_of_year'].astype(str), format='%Y-%j')
df['date'] = d
sub = df[(df['merchant']=='Belles_cookbook_store') & (df['date'].dt.year==2023) & (df['date'].dt.month==7)].copy()

with open('data/fees.json') as f:
    fees = json.load(f)

merchant = {'merchant': 'Belles_cookbook_store', 'capture_delay': '1', 'acquirer': ['lehman_brothers'], 'merchant_category_code': 5942, 'account_type': 'R'}

monthly_volume = sub['eur_amount'].sum()
fraud_vol = sub[sub['has_fraudulent_dispute']==True]['eur_amount'].sum()
fraud_level = fraud_vol / monthly_volume

def match_vol(rule_vol, vol):
    if rule_vol is None: return True
    def parse(x):
        x=x.replace('k','e3').replace('m','e6')
        return float(x)
    if '-' in rule_vol:
        a,b = rule_vol.split('-')
        return parse(a) <= vol < parse(b)
    if rule_vol.startswith('>'): return vol > parse(rule_vol[1:])
    if rule_vol.startswith('<'): return vol < parse(rule_vol[1:])
    return False

def match_fraud(rule, val):
    if rule is None: return True
    val_pct = val*100
    r = rule.replace('%','')
    if '-' in r:
        a,b = r.split('-')
        return float(a) <= val_pct < float(b)
    if r.startswith('>'): return val_pct > float(r[1:])
    if r.startswith('<'): return val_pct < float(r[1:])
    return False

def match_capture(rule, cap):
    if rule is None: return True
    try:
        cap_i = int(cap)
    except:
        return rule == cap
    if rule == 'immediate': return cap_i==0
    if rule == 'manual': return False
    if rule.startswith('>'): return cap_i > int(rule[1:])
    if rule.startswith('<'): return cap_i < int(rule[1:])
    if '-' in rule:
        a,b = rule.split('-')
        return int(a) <= cap_i <= int(b)
    return False

def find_fees(row):
    cands = []
    for f in fees:
        if f['card_scheme'] != row['card_scheme']: continue
        if f['account_type'] and merchant['account_type'] not in f['account_type']: continue
        if f['merchant_category_code'] and merchant['merchant_category_code'] not in f['merchant_category_code']: continue
        if f['is_credit'] is not None and f['is_credit'] != row['is_credit']: continue
        if f['aci'] and row['aci'] not in f['aci']: continue
        if not match_capture(f['capture_delay'], merchant['capture_delay']): continue
        if not match_vol(f['monthly_volume'], monthly_volume): continue
        if not match_fraud(f['monthly_fraud_level'], fraud_level): continue
        if f['intracountry'] is not None:
            intra = row['issuing_country']==row['acquirer_country']
            if bool(f['intracountry']) != intra: continue
        cands.append(f)
    return cands

# check unique combos
combos = sub[['card_scheme','is_credit','aci']].drop_duplicates()
for _, r in combos.iterrows():
    fake = {'card_scheme': r['card_scheme'], 'is_credit': r['is_credit'], 'aci': r['aci'], 'issuing_country':'X','acquirer_country':'Y'}
    c = find_fees(fake)
    print(r.tolist(), 'inter:', len(c), '| intra_us:', end=' ')
    fake2 = {'card_scheme': r['card_scheme'], 'is_credit': r['is_credit'], 'aci': r['aci'], 'issuing_country':'US','acquirer_country':'US'}
    c2 = find_fees(fake2)
    print(len(c2))
