import pandas as pd, json

fees = json.load(open('data/fees.json'))
df = pd.read_csv('data/payments.csv')
df = df[(df['merchant']=='Belles_cookbook_store') & (df['day_of_year']>=1) & (df['day_of_year']<=31)].copy()

merchant = {'account_type':'R','capture_delay':'1','mcc':5942}

# Need monthly_volume and monthly_fraud_level for this merchant in Jan
total_vol = df['eur_amount'].sum()
fraud_vol = df.loc[df['has_fraudulent_dispute']==True,'eur_amount'].sum()
fraud_ratio = fraud_vol/total_vol
print('Total vol:', total_vol, 'Fraud ratio:', fraud_ratio)

def vol_match(rule_vol, v):
    if rule_vol is None: return True
    # forms: '100k-1m', '<100k', '>5m', etc
    s = rule_vol.replace('k','e3').replace('m','e6')
    if '-' in s:
        lo,hi = s.split('-')
        return float(lo)<=v<float(hi)
    if s.startswith('<'):
        return v < float(s[1:])
    if s.startswith('>'):
        return v > float(s[1:])
    return False

def fraud_match(rule_f, f):
    if rule_f is None: return True
    s = rule_f.replace('%','')
    if '-' in s:
        lo,hi = s.split('-')
        return float(lo)/100 <= f < float(hi)/100
    if s.startswith('<'):
        return f < float(s[1:])/100
    if s.startswith('>'):
        return f > float(s[1:])/100
    return False

def capture_match(rule_c, mc):
    if rule_c is None: return True
    # merchant capture delay is "1" -> < 3
    try:
        md = int(mc)
    except:
        md = None
    if rule_c == 'immediate':
        return md == 0
    if rule_c == 'manual':
        return mc == 'manual'
    if rule_c == '<3':
        return md is not None and md < 3
    if rule_c == '3-5':
        return md is not None and 3<=md<=5
    if rule_c == '>5':
        return md is not None and md > 5
    return False

def find_fee(scheme, is_credit, aci, intracountry):
    matches = []
    for r in fees:
        if r['card_scheme']!=scheme: continue
        if r['account_type'] and merchant['account_type'] not in r['account_type']: continue
        if r['merchant_category_code'] and merchant['mcc'] not in r['merchant_category_code']: continue
        if r['is_credit'] is not None and r['is_credit']!=bool(is_credit): continue
        if r['aci'] and aci not in r['aci']: continue
        if r['intracountry'] is not None and r['intracountry']!=intracountry: continue
        if not capture_match(r['capture_delay'], merchant['capture_delay']): continue
        if not vol_match(r['monthly_volume'], total_vol): continue
        if not fraud_match(r['monthly_fraud_level'], fraud_ratio): continue
        matches.append(r)
    return matches

# For each transaction compute fee under its current card scheme, and also 'if we steer everything to X'
# The question: to which scheme should we steer traffic - i.e., pick the scheme with minimum total fees if all transactions used it
schemes = ['GlobalCard','NexPay','TransactPlus','SwiftCharge']

# intracountry: issuing_country == acquirer_country
df['intracountry'] = df['issuing_country']==df['acquirer_country']

results = {}
for sc in schemes:
    total_fee = 0
    unmatched = 0
    for _,row in df.iterrows():
        ms = find_fee(sc, row['is_credit'], row['aci'], row['intracountry'])
        if not ms:
            unmatched += 1
            continue
        # If multiple, pick first? Use average? Typically one applies. Let's pick min
        best = min(ms, key=lambda r: r['fixed_amount']+r['rate']*row['eur_amount']/10000)
        total_fee += best['fixed_amount'] + best['rate']*row['eur_amount']/10000
    results[sc] = (total_fee, unmatched)

for k,v in results.items(): print(k,v)
