def parse_range(s, val):
    if s is None: return True
    s2 = s.replace('%','')
    def conv(x):
        x=x.strip()
        if x.endswith('k'): return float(x[:-1])*1000
        if x.endswith('m'): return float(x[:-1])*1_000_000
        return float(x)
    if s2.startswith('>'): return val > conv(s2[1:])
    if s2.startswith('<'): return val < conv(s2[1:])
    if '-' in s2:
        a,b = s2.split('-'); return conv(a) <= val <= conv(b)
    return True

mv = monthly.loc[sample['month'],'total_vol']
fr = monthly.loc[sample['month'],'fraud_rate']

# For sample: GlobalCard, credit=True, aci=E, mcc=7372, intra=False, acct=D, capture='>5', mv=212k, fr=9.9%
