    if f['is_credit'] is not None and f['is_credit'] != sample['is_credit']: reasons.append(f"credit:{f['is_credit']}")
    if f['aci'] and sample['aci'] not in f['aci']: reasons.append(f"aci:{f['aci']}")
    if f['intracountry'] is not None:
        intra = (sample['issuing_country'] == sample['acquirer_country'])
        if bool(f['intracountry']) != intra: reasons.append(f"intra:{f['intracountry']}")
    if f['monthly_volume'] is not None and not parse_range(f['monthly_volume'], mv): reasons.append(f"mv:{f['monthly_volume']}")
    if f['monthly_fraud_level'] is not None and not parse_range(f['monthly_fraud_level'], fr): reasons.append(f"fr:{f['monthly_fraud_level']}")
    if len(reasons)<=2:
        print("ID:",f['ID'],"fail:",reasons)
