python3 << 'EOF'
import pandas as pd, json
df = pd.read_csv('data/payments.csv')
df['date'] = pd.to_datetime(df['year']*1000 + df['day_of_year'], format='%Y%j')
df['month'] = df['date'].dt.month
rafa = df[(df['merchant']=='Rafa_AI') & (df['month']==7)].copy()
fraud = rafa[rafa['has_fraudulent_dispute']==True].copy()

with open('data/fees.json') as f:
    fees = json.load(f)

# Merchant characteristics
mcc = 7372
account_type = 'D'
capture_delay = '7'  # >5
# July monthly volume
july_vol = rafa['eur_amount'].sum()
# volume bucket: 100k-1m
# fraud level: ~9.9% 

def matches(rule, txn, aci):
    if rule['card_scheme'] != txn['card_scheme']: return False
    if rule['account_type'] and account_type not in rule['account_type']: return False
    if rule['capture_delay'] is not None:
        cd = rule['capture_delay']
        # capture_delay 7 means >5
        if cd == '>5':
            pass
        elif cd == '<3':
            return False
        elif cd == '3-5':
            return False
        elif cd == 'immediate':
            return False
        elif cd == 'manual':
            return False
    if rule['monthly_fraud_level'] is not None:
        # 9.9%
        r = rule['monthly_fraud_level']
        # parse
        if '%' in r:
            parts = r.replace('%','').split('-')
            if len(parts)==2:
                lo, hi = float(parts[0]), float(parts[1])
                if not (lo <= 9.9 <= hi): return False
            else:
                # like '>8.3%'
                if r.startswith('>'):
                    v = float(r[1:].replace('%',''))
                    if not (9.9 > v): return False
                elif r.startswith('<'):
                    v = float(r[1:].replace('%',''))
                    if not (9.9 < v): return False
    if rule['monthly_volume'] is not None:
        r = rule['monthly_volume']
        # 212k => '100k-1m'
        # Handle
        def parseVol(x):
            x = x.replace('k','000').replace('m','000000')
            return float(x)
        if '-' in r:
            lo,hi = r.split('-')
            lo,hi = parseVol(lo), parseVol(hi)
            if not (lo <= july_vol <= hi): return False
        elif r.startswith('>'):
            v = parseVol(r[1:])
            if not (july_vol > v): return False
        elif r.startswith('<'):
            v = parseVol(r[1:])
            if not (july_vol < v): return False
    if rule['merchant_category_code'] and mcc not in rule['merchant_category_code']: return False
    if rule['is_credit'] is not None:
        if rule['is_credit'] != txn['is_credit']: return False
    if rule['aci'] and aci not in rule['aci']: return False
    if rule['intracountry'] is not None:
        intra = txn['issuing_country'] == txn['acquirer_country']
        if rule['intracountry'] != intra: return False
    return True

def compute_fee(txn, aci):
    for rule in fees:
        if matches(rule, txn, aci):
            return rule['fixed_amount'] + rule['rate']*txn['eur_amount']/10000
    return None

# For each possible ACI (not G), compute total cost across all fraud txns
acis = ['A','B','C','D','E','F']
results = {}
for aci in acis:
    total = 0
    missing = 0
    for _, txn in fraud.iterrows():
        fee = compute_fee(txn, aci)
        if fee is None:
            missing += 1
        else:
            total += fee
    results[aci] = (total, missing)
    print(f"ACI {aci}: total={total:.2f} missing={missing}")

# Current cost with G
total_g = 0
for _, txn in fraud.iterrows():
    fee = compute_fee(txn, 'G')
    if fee is None:
        continue
    total_g += fee
print(f"Current G: total={total_g:.2f}")
