vol = m['eur_amount'].sum()
fraud_rate = m[m['has_fraudulent_dispute']==True]['eur_amount'].sum()/vol *100

def volume_match(rule_val, v):
    if rule_val is None: return True
    s = rule_val
    def parse(x):
        x=x.strip()
        if x.endswith('k'): return float(x[:-1])*1e3
        if x.endswith('m'): return float(x[:-1])*1e6
        return float(x)
    if s.startswith('>'): return v > parse(s[1:])
    if s.startswith('<'): return v < parse(s[1:])
    if '-' in s:
        lo,hi = s.split('-')
        return parse(lo) <= v < parse(hi)
    return False

def fraud_match(rule_val, fr):
    if rule_val is None: return True
    s = rule_val
    if s.startswith('<'):
        return fr < float(s[1:].replace('%',''))
    if s.startswith('>'):
        return fr > float(s[1:].replace('%',''))
    if '-' in s:
        lo,hi = s.split('-')
        return float(lo.replace('%','')) <= fr < float(hi.replace('%',''))
    return False

def rule_matches(rule, tx, vol, fraud_rate, mer):
    if rule['card_scheme'] != tx['card_scheme']: return False
    if rule['account_type'] and mer['account_type'] not in rule['account_type']: return False
    if rule['merchant_category_code'] and mer['merchant_category_code'] not in rule['merchant_category_code']: return False
    if rule['is_credit'] is not None and rule['is_credit'] != tx['is_credit']: return False
    if rule['aci'] and tx['aci'] not in rule['aci']: return False
    if rule['capture_delay'] is not None and rule['capture_delay'] != mer['capture_delay']: return False
    intracountry = tx['issuing_country']==tx['acquirer_country']
    if rule['intracountry'] is not None and bool(rule['intracountry']) != intracountry: return False
    if not volume_match(rule['monthly_volume'], vol): return False
    if not fraud_match(rule['monthly_fraud_level'], fraud_rate): return False
    return True

# Find unmatched pattern
unmatched_pat = {}
for _,tx in m.iterrows():
    matched = [r for r in fees if rule_matches(r, tx, vol, fraud_rate, mer)]
    if not matched:
        key = (tx['card_scheme'], tx['is_credit'], tx['aci'], tx['issuing_country']==tx['acquirer_country'])
        unmatched_pat[key] = unmatched_pat.get(key,0)+1
print(unmatched_pat)
