python3 <<'EOF'
import pandas as pd, json
df = pd.read_csv('data/payments.csv')
merchants = json.load(open('data/merchant_data.json'))
fees = json.load(open('data/fees.json'))

merchant_name='Golfclub_Baron_Friso'
minfo = [m for m in merchants if m['merchant']==merchant_name][0]
sub_day = df[(df.merchant==merchant_name) & (df.year==2023) & (df.day_of_year==365)].copy()
mdf = df[(df.merchant==merchant_name) & (df.year==2023) & (df.day_of_year>=335) & (df.day_of_year<=365)]
monthly_volume = mdf['eur_amount'].sum()
fraud_volume = mdf[mdf['has_fraudulent_dispute']==True]['eur_amount'].sum()
fraud_ratio = fraud_volume/monthly_volume

def parse_range(rng, val):
    def pv(s):
        s=s.strip()
        if s=='': return None
        if s.endswith('k'): return float(s[:-1])*1e3
        if s.endswith('m'): return float(s[:-1])*1e6
        if s.endswith('%'): return float(s[:-1])/100
        return float(s)
    if rng is None: return True
    if '-' in rng and not rng.startswith('-') and not rng.startswith('<') and not rng.startswith('>'):
        parts = rng.split('-')
        lo,hi = pv(parts[0]),pv(parts[1])
        return lo<=val<=hi
    if rng.startswith('<'):
        return val < pv(rng[1:])
    if rng.startswith('>'):
        return val > pv(rng[1:])
    return True

def match_fee(rule, tx, minfo, monthly_volume, fraud_ratio):
    if rule['card_scheme'] != tx['card_scheme']: return False
    if rule['account_type'] and minfo['account_type'] not in rule['account_type']: return False
    if rule['capture_delay'] is not None:
        cd = minfo['capture_delay']
        rd = rule['capture_delay']
        try: cdv = int(cd)
        except: cdv = None
        if rd=='<3':
            if cdv is None or cdv>=3: return False
        elif rd=='>5':
            if cdv is None or cdv<=5: return False
        elif rd=='3-5':
            if cdv is None or not (3<=cdv<=5): return False
        elif rd=='immediate':
            if cd!='immediate': return False
        elif rd=='manual':
            if cd!='manual': return False
        else:
            if cd!=rd: return False
    if rule['monthly_fraud_level'] is not None:
        if not parse_range(rule['monthly_fraud_level'], fraud_ratio): return False
    if rule['monthly_volume'] is not None:
        if not parse_range(rule['monthly_volume'], monthly_volume): return False
    if rule['merchant_category_code'] and minfo['merchant_category_code'] not in rule['merchant_category_code']: return False
    if rule['is_credit'] is not None and rule['is_credit'] != bool(tx['is_credit']): return False
    if rule['aci'] and tx['aci'] not in rule['aci']: return False
    if rule['intracountry'] is not None:
        intra = (tx['issuing_country']==tx['acquirer_country'])
        if bool(rule['intracountry']) != intra: return False
    return True

total_fee=0
unmatched_rows=[]
matched_rows=[]
for _,tx in sub_day.iterrows():
    matched = [r for r in fees if match_fee(r, tx, minfo, monthly_volume, fraud_ratio)]
    if not matched:
        unmatched_rows.append((tx['card_scheme'],tx['is_credit'],tx['aci'],tx['issuing_country']==tx['acquirer_country']))
    else:
        matched_rows.append((tx['card_scheme'],tx['is_credit'],tx['aci'],tx['issuing_country']==tx['acquirer_country'],len(matched),[m['ID'] for m in matched]))

from collections import Counter
print("Unmatched groups:", Counter(unmatched_rows))
print("Matched groups:")
for m in matched_rows: print(m)
EOF

