python3 << 'EOF'
import pandas as pd, json

df = pd.read_csv('data/payments.csv')
with open('data/fees.json') as f: fees = json.load(f)

mcc = 7997
account_type = 'F'
capture_delay = 'manual'
monthly_volume = '100k-1m'
monthly_fraud_level = '>8.3%'

sub = df[(df.merchant=='Crossfit_Hanna') & (df.year==2023) & (df.day_of_year==365)].copy()
sub['intracountry'] = (sub.issuing_country == sub.acquirer_country)

# Check first unmatched
def match(rule, tx, verbose=False):
    reasons=[]
    if rule['card_scheme'] != tx['card_scheme']: reasons.append('cs')
    if rule['account_type'] and account_type not in rule['account_type']: reasons.append('at')
    if rule['capture_delay'] is not None and rule['capture_delay'] != capture_delay: reasons.append('cd')
    if rule['monthly_fraud_level'] is not None and rule['monthly_fraud_level'] != monthly_fraud_level: reasons.append('mf')
    if rule['monthly_volume'] is not None and rule['monthly_volume'] != monthly_volume: reasons.append('mv')
    if rule['merchant_category_code'] and mcc not in rule['merchant_category_code']: reasons.append('mcc')
    if rule['is_credit'] is not None and rule['is_credit'] != tx['is_credit']: reasons.append('ic')
    if rule['aci'] and tx['aci'] not in rule['aci']: reasons.append('aci')
    if rule['intracountry'] is not None:
        if bool(rule['intracountry']) != bool(tx['intracountry']): reasons.append('intra')
    return len(reasons)==0

# look at a specific tx that is unmatched
for i, tx in sub.iterrows():
    matches = [r for r in fees if match(r, tx)]
    if not matches:
        print(tx.card_scheme, tx.aci, tx.is_credit, tx.intracountry, tx.eur_amount)
        # find rules that match on card_scheme + mcc + aci
        for r in fees:
            if r['card_scheme']==tx.card_scheme and (not r['merchant_category_code'] or mcc in r['merchant_category_code']) and (not r['aci'] or tx.aci in r['aci']):
                print("  candidate:", r)
        break
