arguments.command:
python3 << 'EOF'
import pandas as pd, json

df = pd.read_csv('data/payments.csv')
fees = json.load(open('data/fees.json'))
merchant = {'account_type':'F','merchant_category_code':7993,'capture_delay':'2'}

row = df[df['psp_reference']==40389346639].iloc[0]
# vol/fraud placeholder
total_vol = 215682.64
fraud_ratio = 0.1076

def cap_match(rule_cd, mcd):
    if rule_cd is None: return True
    try: d=int(mcd)
    except: return rule_cd==mcd
    if rule_cd=='immediate': return d==0
    if rule_cd=='<3': return d<3
    if rule_cd=='3-5': return 3<=d<=5
    if rule_cd=='>5': return d>5
    if rule_cd=='manual': return False
    return False

def vol_match(rule_v, vol):
    if rule_v is None: return True
    def parse(s):
        s=s.replace('k','e3').replace('m','e6')
        return float(s)
    if '-' in rule_v:
        a,b=rule_v.split('-'); return parse(a)<=vol<=parse(b)
    if rule_v.startswith('<'): return vol<parse(rule_v[1:])
    if rule_v.startswith('>'): return vol>parse(rule_v[1:])
    return False

def fraud_match(rule_f, fr):
    if rule_f is None: return True
    frp=fr*100
    if '-' in rule_f:
        a,b=rule_f.split('-'); return float(a.replace('%',''))<=frp<=float(b.replace('%',''))
    if rule_f.startswith('<'): return frp<float(rule_f[1:].replace('%',''))
    if rule_f.startswith('>'): return frp>float(rule_f[1:].replace('%',''))
    return False

for r in fees:
    if r['card_scheme']!=row['card_scheme']: continue
    fail=[]
    if r['account_type'] and merchant['account_type'] not in r['account_type']: fail.append('acct')
    if r['merchant_category_code'] and merchant['merchant_category_code'] not in r['merchant_category_code']: fail.append('mcc')
    if not cap_match(r['capture_delay'], merchant['capture_delay']): fail.append('cap')
    if not vol_match(r['monthly_volume'], total_vol): fail.append('vol')
    if not fraud_match(r['monthly_fraud_level'], fraud_ratio): fail.append('fraud')
    if r['is_credit'] is not None and r['is_credit']!=row['is_credit']: fail.append('cred')
    if r['aci'] and row['aci'] not in r['aci']: fail.append('aci')
    if r['intracountry'] is not None:
        intra=(row['issuing_country']==row['acquirer_country'])
        if bool(r['intracountry'])!=intra: fail.append('intra')
    if len(fail)<=1:
        print(r['ID'], fail, r)
